(window.RAGHIB_FULL = window.RAGHIB_FULL || {})["2-8"] = [{"a": [189], "v": 1, "p": 401, "ev": 1, "ep": 404, "sid": 402, "t": "﴿يَسۡـَٔلُونَكَ عَنِ ٱلۡأَهِلَّةِۖ قُلۡ هِيَ مَوَٰقِيتُ لِلنَّاسِ وَٱلۡحَجِّۗ وَلَيۡسَ ٱلۡبِرُّ بِأَن تَأۡتُواْ ٱلۡبُيُوتَ مِن ظُهُورِهَا وَلَٰكِنَّ ٱلۡبِرَّ مَنِ ٱتَّقَىٰۗ وَأۡتُواْ ٱلۡبُيُوتَ مِنۡ أَبۡوَٰبِهَاۚ وَٱتَّقُواْ ٱللَّهَ لَعَلَّكُمۡ تُفۡلِحُونَ﴾⟪2:189⟫ الآية (189) - سورة البقرة.\nالمواقيت: جمع ميقات وهو مفعال من الوقت، والوقت والمدة والزمان تتقارب لكن المدة المطلقة أوسع هذه الألفاظ، فإنها امتداد حركة الفلك أي اتصالها من مبدئها إلى غايتها، والزمان مدة مقسومة من المدة المطلقة والوقت الزمان المفروض للعمل ومعنى مواقيت للناس أي لا يتعلق به من أمور معاملاتهم ومصالحهم، كقوله تعالى: ﴿هُوَ ٱلَّذِي جَعَلَ ٱلشَّمۡسَ ضِيَآءٗ وَٱلۡقَمَرَ نُورٗا وَقَدَّرَهُۥ مَنَازِلَ لِتَعۡلَمُواْ عَدَدَ ٱلسِّنِينَ وَٱلۡحِسَابَۚ﴾⟪10:5⟫ ونبه بذكر الحج على ما يتعلق به من العبادات، ولكن ذكرنا\n⟦1:402⟧\nأعظمها أثرا فإن الحج مراعى في قضائه وأدائه الوقت المعلوم وبخلاف سائر العبادات التي لا تعتبر في قضائها وقت معين والباب معروف وعنه أستعير لمداخل الأسباب المتوصل بها إليه، وقيل: في العلم باب كذا، وقول النبي - صلى الله عليه وسلم -: \" أنا مدينة العلم وعلي بابها \"، أي به يتواصل إلى حقائق العلوم وعلي وإن شاركه فيه غيره، فتخصيصه لكونه أرفع منزلة في باب العلم وقد كان سئل - عليه السلام - عن فائدة زيادة الهلال ونقصانه، فأنزل الله تعالى هذه الآية منبها على أظهر فائدته للحس وأبينها له، ثم قال: ﴿لَّيۡسَ ٱلۡبِرَّ أَن تُوَلُّواْ وُجُوهَكُمۡ قِبَلَ ٱلۡمَشۡرِقِ وَٱلۡمَغۡرِبِ﴾⟪2:177⟫، أي بأن يطلبوا من غير وجه، وذلك أنه يقال: \" أتى فلان البيت من بابه \" إذا طلب الشيء من وجهه.\nوقال الشاعر:\nأتيت المروءة من بابها ..\n⟦1:403⟧\nو \" أتى البيت من ظهره \" إذا طلب الأمر من غير وجهه وجعل ذلك مثلا لسؤالهم النبي - صلى الله عليه وسلم - عما هو ليس من العلم المختص بالنبوة، وأن ذلك عدول عن المنهج وذلك أن العلوم ضربان:\nدنيوي: يتعلق بأمر المعاش كمعرفة الصنايع ومعرفة الأجرام السماوية ومعرفة المعادن والنبات وطبائع الحيوانات، وقد جعل الله تعالى لنا سبيلا إلى معرفته على غير لسان نبيه محمد - عليه السلام -، وشرعي: وهو البر، ولا سبيل إلى أخذه إلا من جهته وهو أحكام التقوى، فلما جاءوا يسألون النبي - صلى الله عليه وسلم - عما أمكنهم معرفته من غير جهته أجابهم ثم بين لهم أن ليس البر ترك المنهج في سؤال النبي - عليه السلام - ما ليس هو مختصا بعلم نبوته ولكن البر هو تحري التقوى، وذلك يكون بالعلم والعمل المختصين بالدين وقال بعض المفسرين إتيان البيوت من ظهورها هو أن العرب من لم يكن من الخمس إذا أحرم لم يدخل البيت من بابه بل كان يأتيه من ظهوره، فأتى رجل من باب بيته، فأنكر عليه، فأنزل الله تعالى هذه الآية ..\nوهذا عن ابن عباس وغيره وقيل: إتيان البيوت من ظهورها مخالفة الواجب في الحج وشهوره واستحلال أشهر الحرام وتحريم الحلال، المعنى بقوله: ﴿إِنَّمَا ٱلنَّسِيٓءُ زِيَادَةٞ فِي ٱلۡكُفۡرِۖ﴾⟪9:37⟫ وكل ذلك لا يمتنع أن تتناوله الآية لكن الأليق بأول الآية ما تقدم ذكره، وقوله: ﴿وَأۡتُواْ ٱلۡبُيُوتَ مِنۡ أَبۡوَٰبِهَاۚ﴾⟪2:189⟫ أي تحروا في كل عمل إتيان الشيء من وجهه تنبيها أن ما يطلب من غير وجهه صعب مناله، ثم قال: ﴿وَٱتَّقُواْ ٱللَّهَ﴾⟪2:189⟫ حثا لنا أن نجعل تقوى الله عز وجل- شعارنا في كل ما نتحراه، فبين أن ذلك هو الذريعة إلى تحصيل الفلاح ..\n⟦1:404⟧"}, {"a": [190], "v": 1, "p": 404, "ev": 1, "ep": 405, "sid": 405, "t": "قوله - عز وجل:\n﴿وَقَٰتِلُواْ فِي سَبِيلِ ٱللَّهِ ٱلَّذِينَ يُقَٰتِلُونَكُمۡ وَلَا تَعۡتَدُوٓاْۚ إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلۡمُعۡتَدِينَ﴾⟪2:190⟫\nالآية (190) - سورة البقرة.\nاختلف في حكم هذه الآية، فقيل: هي ناسخة لحكم العفو ومنسوخة بقوله: ﴿وَقَٰتِلُواْ ٱلۡمُشۡرِكِينَ كَآفَّةٗ﴾⟪9:36⟫ وقيل: ليست بمنسوخة ولا ناسخة، وبيان ذلك أن من شرط الداعي إلى الحق أن يبينه ويدل عليه ويرفق، فإن اهتدى المدعو، وإلا أوعد، فإن أنجع ذلك وإلا عدل بعد إلى المحاسبة والمحاربة على ما تقتضيه السياسة، وعلى هذا قال بعضهم: \" لا أستعمل سوطي ما كفاني لساني ولا سيفي ما كفاني سوطي \".\nوقال الشاعر:\nأناة فإن لم يغن أعقب بعدها\n....\nوعيدا فإن لم يغن أغنت عزائمه\nفكان النبي - صلى الله عليه وسلم - أمر في أول الأمر بالرفق والأناة، وأن يقتصر على الوعظ والمجادلة الحسنة، كما قال تعالى:\n﴿ٱدۡعُ إِلَىٰ سَبِيلِ رَبِّكَ بِٱلۡحِكۡمَةِ وَٱلۡمَوۡعِظَةِ ٱلۡحَسَنَةِۖ وَجَٰدِلۡهُم بِٱلَّتِي هِيَ أَحۡسَنُۚ﴾⟪16:125⟫، وكان يستمر على ذلك حتى عاتبه بعض أصحابها فقال يا نبي الله:\n⟦1:405⟧\n\" كنا في عز ونحن مشركون، فلما آمنا صرنا أذلة \"، فقال عليه السلام: \" أمرت بالعفو فلا تقاتلوهم اليوم \"، فلما ظهرت آياته، وانتشرت بنياته، ورأى من أبى الإصغاء إلى الحق، واستمر على الضلال والإضلال أمر حينئذ بالمقاتلة أي المحاربة، ولهذا قال تعالى:\n﴿أَلَمۡ تَرَ إِلَى ٱلَّذِينَ قِيلَ لَهُمۡ كُفُّوٓاْ أَيۡدِيَكُمۡ وَأَقِيمُواْ ٱلصَّلَوٰةَ وَءَاتُواْ ٱلزَّكَوٰةَ فَلَمَّا كُتِبَ عَلَيۡهِمُ ٱلۡقِتَالُ إِذَا فَرِيقٞ مِّنۡهُمۡ يَخۡشَوۡنَ ٱلنَّاسَ كَخَشۡيَةِ ٱللَّهِ أَوۡ أَشَدَّ خَشۡيَةٗۚ﴾⟪4:77⟫\nثم أمر بالقتال لمن تأبى الرجوع إلى الحق بالمحاربة، وكان هذا أمرا بعد أمر حسب مقتضى السياسة الإلهية، وقوله: ﴿ٱلَّذِينَ يُقَٰتِلُونَكُمۡ﴾⟪2:190⟫ منهم من تصور منه تولي القتال وتعاطيه في الحال، فقال: هو منسوخ بقوله: ﴿وَقَٰتِلُواْ ٱلۡمُشۡرِكِينَ كَآفَّةٗ﴾⟪9:36⟫، (ولا تعتدوا): نهي عام في مجاوزة كل حد حده الله تعالى، كالنهي عن قتل الصبيان والنساء وقيل: \" من أعطي الأمان وتحرى القتال ابتغى عرض الدنيا وطلب الرئاسة \"، ونبه بقوله: ﴿إِنَّ ٱللَّهَ لَا يُحِبُّ ٱلۡمُعۡتَدِينَ﴾⟪2:190⟫ أن اعتداء مرسوم الله وتجاوز حكمه في كل أمر مذموم .."}, {"a": [191], "v": 1, "p": 405, "ev": 1, "ep": 407, "sid": 406, "t": "قوله- عز وجل:\n﴿وَٱقۡتُلُوهُمۡ حَيۡثُ ثَقِفۡتُمُوهُمۡ وَأَخۡرِجُوهُم مِّنۡ حَيۡثُ أَخۡرَجُوكُمۡۚ وَٱلۡفِتۡنَةُ أَشَدُّ مِنَ ٱلۡقَتۡلِۚ وَلَا تُقَٰتِلُوهُمۡ عِندَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ حَتَّىٰ يُقَٰتِلُوكُمۡ فِيهِۖ فَإِن قَٰتَلُوكُمۡ فَٱقۡتُلُوهُمۡۗ كَذَٰلِكَ جَزَآءُ ٱلۡكَٰفِرِينَ﴾⟪2:191⟫\nالآية (191) - سورة البقرة.\nالثقف: الحذق في إدراك الشيء علما كان أو عملا، ومنه قيل:\nرجل ثقف لقف إذا كان له حذق في إدراك الشيء علما كان أو عملا، ومنه قيل: رجل ثقف لقف إذا كان له خدمة في إدراك الشيء ومنه قيل: ثقفت الرمح ، وأصل الفتنة إدخال الذهب النار للتصفية، يقال: فتنت الذهب أي اختبرته بالنار، ثم استعير لكل اختبار بأمر محض، على ذلك قوله تعالى:\n⟦1:406⟧\n﴿أَحَسِبَ ٱلنَّاسُ أَن يُتۡرَكُوٓاْ أَن يَقُولُوٓاْ ءَامَنَّا وَهُمۡ لَا يُفۡتَنُونَ﴾⟪29:2⟫\nوجعل الفتنة لكل أمر مكروه المحتمل، فتارة استعير للشرك، وتارة للعذاب، وتارة للاختبار، ولما كان لفظ الفتنة والقتل ههنا مبهمين، قال بعضهم: معناه أن يفتن الإنسان في دينه، فيشرك أشد أي أوخم عاقبة من أن يقتل، فإن الأذية التي تنال المقتول محدودة، والأذية التي تنال الشرك بشركه غير محدودة، وقال بعضهم: إن معناه: أن يوقع الإنسان الفتنة أشد على الناس أي أعظم ضررا من أن يقتل في الحرم من يستحق القتل، وقال: وذلك رد على من استعظم قتل بعض المسلمين كافرا في الحرم، ولهذا قال بعده: ﴿وَقَٰتِلُوهُمۡ حَتَّىٰ لَا تَكُونَ فِتۡنَةٞ﴾⟪2:193⟫ وقوله ﴿وَأَخۡرِجُوهُم﴾⟪2:191⟫ أمر بإخراج الكفار من مكة بدلالة قوله: ﴿وَكَأَيِّن مِّن قَرۡيَةٍ هِيَ أَشَدُّ قُوَّةٗ مِّن قَرۡيَتِكَ ٱلَّتِيٓ أَخۡرَجَتۡكَ﴾⟪47:13⟫، وقوله: ﴿لِلۡفُقَرَآءِ ٱلۡمُهَٰجِرِينَ ٱلَّذِينَ أُخۡرِجُواْ مِن دِيَٰرِهِمۡ وَأَمۡوَٰلِهِمۡ﴾⟪59:8⟫ وقوله: ﴿وَلَا تُقَٰتِلُوهُمۡ عِندَ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ﴾⟪2:191⟫ استثناء من قوله: ﴿وَٱقۡتُلُوهُمۡ حَيۡثُ ثَقِفۡتُمُوهُمۡ﴾⟪2:191⟫، وهذا حكم عند أكثر الفقهاء فإنه لا يقاتل في الحرم إلا من قاتل، ويؤيد ذلك قوله - عليه السلام - يوم فتح مكة: \" إن مكة حرام حرمها الله - عز وجل - يوم خلق السماوات والأرض وإنما أحلت لي ساعة من نهار، ثم عادت حراما إلي يوم القيامة \"، فهذا يدل على أن ذلك غير منسوخ كما ظنه بعض الناس، وقال الأصم: إن ثبت جوازا القتل هذا في\n⟦1:407⟧\nالحرم، فليس في ذلك نسخ، بل هو زيادة في فرض القتال، فإن هذا أمر بأن يقاتلوا في الحرم إذا قوتلوا، وذاك أمر بالقتل قوتلوا أو لم يقاتلوا، فإذن الثاني زيادة في الأمر بالقتال، ثم قال: ﴿فَإِن قَٰتَلُوكُمۡ﴾⟪2:191⟫، أي حاربوكم فاقتلوهم، وبين أن هذا حكم كل كافر يحارب المؤمنين."}, {"a": [192], "v": 1, "p": 407, "ev": 1, "ep": 408, "sid": 408, "t": "قوله - عز وجل:\n﴿فَإِنِ ٱنتَهَوۡاْ فَإِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ﴾⟪2:192⟫ الآية (192) - سورة البقرة.\nالانتهاء: الانزجار، والنهي الزجر، ونهاية الشيء غايته التي ينتهي إليها، لأن لكل شيء في هذا العالم غاية إذا انتهى إليها انصرف راجعا عنها في الكون والفساد والنهي العقل لكونه ناهيا عن القبيح، ككون العقل عاقلا عنه، والحجر حاجرا عنه، والنهي في موضوع أهل النحو من صيغة \" لا تفعل \" حثا على الشيء كان أو زجرا عنه، وفي موضوع أهل البرهان ما يقتضي الزجر عن الشيء سواء كان بلفظ \" أفعل \" أو \" لا تفعل \"، وهذا الخلاف من أجل أن النحوي يعتبر اللفظ قبل المعنى، وصاحب البرهان يعتبر المعنى قبل اللفظ، ونبه بالآية أن المنتهي عن الذنب يغفر له ما تقدم من ذنبه، وذلك عام في أمور الدنيا والآخرة إلا ما دلت الدلالة على الأخذ به من حقوق الآدميين، وعلى هذا قوله - عز وجل: ﴿قُل لِّلَّذِينَ كَفَرُوٓاْ إِن يَنتَهُواْ يُغۡفَرۡ لَهُم مَّا قَدۡ سَلَفَ﴾⟪8:38⟫، وقوله عليه السلام: \" الإسلام يجب ما قبله \" ..\n⟦1:408⟧"}, {"a": [193], "v": 1, "p": 408, "ev": 1, "ep": 408, "sid": 409, "t": "قوله - عز وجل:\n﴿وَقَٰتِلُوهُمۡ حَتَّىٰ لَا تَكُونَ فِتۡنَةٞ وَيَكُونَ ٱلدِّينُ لِلَّهِۖ فَإِنِ ٱنتَهَوۡاْ فَلَا عُدۡوَٰنَ إِلَّا عَلَى ٱلظَّٰلِمِينَ﴾⟪2:193⟫\nالآية (193) - سورة البقرة.\nأمر تعالى بالقتال لدفع الفتنة بعد أن يبين أنها أعظم ضررا من القتل، نحو قوله: ﴿فَإِذَا لَقِيتُمُ ٱلَّذِينَ كَفَرُواْ فَضَرۡبَ ٱلرِّقَابِ حَتَّىٰٓ إِذَآ أَثۡخَنتُمُوهُمۡ فَشُدُّواْ ٱلۡوَثَاقَ فَإِمَّا مَنَّۢا بَعۡدُ وَإِمَّا فِدَآءً حَتَّىٰ تَضَعَ ٱلۡحَرۡبُ أَوۡزَارَهَاۚ﴾⟪47:4⟫، فقوله: ﴿حَتَّىٰ لَا تَكُونَ فِتۡنَةٞ﴾⟪2:193⟫ كقوله: ﴿حَتَّىٰ تَضَعَ ٱلۡحَرۡبُ أَوۡزَارَهَاۚ﴾⟪47:4⟫، وذلك إما بقتلهم أو بإسلامهم أو بانقيادهم وإعطاء الجزية حسب ما بينه الشرع، ﴿وَيَكُونَ ٱلدِّينُ لِلَّهِۖ﴾⟪2:193⟫ قال ابن عباس: حتى يخلص التوحيد له \" وحمل ذلك على مشركي العرب، لأنهم لا يقارون على جزية كما يقال غيرهم، وحمل بعضهم على الانقياد بحكم الدين في كل مكان، وقال: يجب أن يكون الحكم للإسلام في كل مكان، وعلى هذا ما روي: \" الإسلام يعلو ولا يعلى \"، ثم أعاد ذكر الانتهاء، فقال: ﴿فَإِنِ ٱنتَهَوۡاْ فَلَا عُدۡوَٰنَ إِلَّا عَلَى ٱلظَّٰلِمِينَ﴾⟪2:193⟫ أي لا يتجاوزون الخطر إلا مع من يتجاوزه بحسب فعله .."}, {"a": [194], "v": 1, "p": 408, "ev": 1, "ep": 410, "sid": 409, "t": "قوله - عز وجل:\n﴿ٱلشَّهۡرُ ٱلۡحَرَامُ بِٱلشَّهۡرِ ٱلۡحَرَامِ وَٱلۡحُرُمَٰتُ قِصَاصٞۚ فَمَنِ ٱعۡتَدَىٰ عَلَيۡكُمۡ فَٱعۡتَدُواْ عَلَيۡهِ بِمِثۡلِ مَا ٱعۡتَدَىٰ عَلَيۡكُمۡۚ وَٱتَّقُواْ ٱللَّهَ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ مَعَ ٱلۡمُتَّقِينَ﴾⟪2:194⟫ الآية (194) - سورة البقرة .\nبين أن مراعاة حرمة الشهر واجبة لمن راعى حرمته، وأن من هتكها اقتص منه، وسبب نزول ذلك أن العرب فخرت بصرف النبي - عليه السلام - عام الحديبية عن البلد الحرام، وكان ذلك في ذي القعدة، فمكنه الله تعالى من دخوله في العام القابل في القعدة، وشرح معنى قوله: ﴿فَلَا عُدۡوَٰنَ إِلَّا عَلَى ٱلظَّٰلِمِينَ﴾⟪2:193⟫ بقوله: ﴿فَمَنِ ٱعۡتَدَىٰ عَلَيۡكُمۡ فَٱعۡتَدُواْ﴾⟪2:194⟫.\nإن قيل: كيف رخص في الاعتداء وهو ظلم وقد منع منه آنفا بقوله: ﴿وَلَا تَعۡتَدُوٓاْۚ﴾، قيل: الاعتداء مجاورة الحد، ومنه قيل: \" عدا فلان طوره \"، و \" لا تعد طورك \"، ثم استعير الاعتداء في الظلم من حيث\n⟦1:409⟧\nأنه تجاوز الحد الذي حده العقل أو الشرع، والذي منع تجاوز ذلك ابتداء، فقد أباح لمن اعتدى عليه جزاء، فإذن: الاعتداء ضربان: اعتداء على سبيل الابتداء، وهو ظلم، وإياه عنى بقوله ولا (تعتدوا) واعتداء على سبيل الاعتداء ضربان اعتداء على سبيل القصاص وهو عدل وإياه عني ههنا، ثم للمجازاة أيضا حد لا يحوز أن يتجاوزه، وإياه عنى بقوله: ﴿فَمَنِ ٱعۡتَدَىٰ بَعۡدَ ذَٰلِكَ﴾.\nإن قيل: هل كان يجوز لو قيل: (من ظلمكم فاظلموهم)؟ قيل: لا يجوز ذلك، لأن الظلم إنما هو وضع الشيء في غير موضعه الذي يحق أن يوضع فيه، وهذا في كل حال مذموم، والاعتداء مجاوزة الحد المحدود، وذلك لا يكون مذموما، ومن قال من العرب: \" من ظلمك فاظلمه \"، فذلك منه انحراف وترخص في الظلم على عادتهم، وكذا قول من قال:\nألا لا يجهلن أحد علينا ...\nفنجهل فوق جهل الجاهلينا\nفإن الجهل مذموم على كل حال، ولا يكاد يرد لفظ الأمر به من حكيم،\nفإن قيل: فقد قال الله: ﴿وَمَكَرُواْ وَمَكَرَ ٱللَّهُۖ﴾⟪3:54⟫ قيل: حقيقة المكر إظهار أمر يعتقد فيه الناظر إليه الجاهل بحقيقته اعتقادا ما يضل ما هو، وكذلك الاحتيال والخديعة والسخرية ومن قصد بشيء من ذلك أمرا قبيحا، فهو مذموم وأن قصد به فعلا جميلا فهو محمود، فإذن يصح أن يمدح بذلك من يتحرى مقصدا حسنا، ولهذا قال بعض العلماء: إن الله - عز وجل - يخدعنا عن النار كما يخدع الصبي أبوه عن المضار، وفي هذه الآية دلالة أن من استهلك شيئا لغيره استهلك عليه مثله، لكن مثله المستهلك قد يكون تارة حسية مكيلا كان أو موزونا أو معدودا، وتارة قيمته، وقوله: ﴿وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ مَعَ ٱلۡمُتَّقِينَ﴾⟪2:194⟫، تنبيه أن توفيق الله يصحب المتقي، وقد تقدم حقيقة (مع) والصحبة إذا استعملا في الباري تعالى ...\n⟦1:410⟧"}, {"a": [195], "v": 1, "p": 410, "ev": 1, "ep": 412, "sid": 411, "t": "قوله - عز وجل:\n﴿وَأَنفِقُواْ فِي سَبِيلِ ٱللَّهِ وَلَا تُلۡقُواْ بِأَيۡدِيكُمۡ إِلَى ٱلتَّهۡلُكَةِ وَأَحۡسِنُوٓاْۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُحۡسِنِينَ﴾⟪2:195⟫\nالآية (195) - سورة البقرة.\nالهلاك انتهاء الشيء في الفساد، وله سمي الموت هلاكا، وقيل للعذاب والخوف في الفقر والبخل وما يجري مجراها مما يؤدي إلى الهلاك هلاكا، والمفازة مهلكة والتهلكة ما يؤدي إلى الهلاك، وامرأة هلوك كأنها تتهالك في مشيها إشارة إلى نحو قول الشاعر:\nمريضات أدبات التهادي كأنما\n....\nتخاف على أحشائها أن تقطعا\n[وكني بالهلوك عن الفاجرة لتماثلها] والهالكي كان رجلا حدادا من قبيلة هالك فسعت العرب كل حداد باسمه كما سمي كل بناء هاجريا، وقوله: ﴿وَلَا تُلۡقُواْ بِأَيۡدِيكُمۡ﴾⟪2:195⟫، قيل: معناه نحو تعلقت زيدا أو بزيد، وقيل معناه: ولا تلقوا أنفسكم بأيديكم إلى الهلاك، نحو قوله: ﴿وَلَا تَقۡتُلُوٓاْ أَنفُسَكُمۡۚ﴾⟪4:29⟫، وذلك بالتعرض لما يستوخم عاقبته جهلا به، مثل الفراشة تأتي إذا رأت لهبا من السراج، فتلقي نفسها فيه، وتأولت الآية على وجهين بنظرين مختلفين ..\nأحدهما: أنه نهي عن الإسراف في الإنفاق، وعن التهور في الإقدام، والثاني: أنه نهي عن البخل بالمال، والقعود عن الجهاد، وكلا المعنيين يراد بها، فالإنسان كما أنه منهي عن الإسراف في\n⟦1:411⟧\n[الإنفاق] والتهور في الإقدام، فهو منهي عن البخل وعن الإحجام في الجهاد، ولهذا قال تعالى:\n﴿وَٱلَّذِينَ إِذَآ أَنفَقُواْ لَمۡ يُسۡرِفُواْ وَلَمۡ يَقۡتُرُواْ﴾⟪25:67⟫، وقال: ﴿وَلَا تَجۡعَلۡ يَدَكَ مَغۡلُولَةً إِلَىٰ عُنُقِكَ وَلَا تَبۡسُطۡهَا كُلَّ ٱلۡبَسۡطِ﴾⟪17:29⟫ الآية، وقال بعض الناس: \" إن هذه الآية ينظر إليها علي وجهين \" أحديهما: نظر المجاهد في سبيل الله بالمال، والثاني: نظر الفقيه عن المجاهد، وكلاهما صحيح بوجه، ووجه ذلك أن الفقيه من حيث أنه يحكم بالظاهر على الكافة يراعي أحوالهم، والمجاهد من حيث أنه يوفر على مراعاة الحق عن مراعاة نفسه لا يرى الإلقاء بيده إلى التهلكة إلى التهلكة إلا الإحلال بترك وظائف الحق، وإلى هذه الحالة أشار الله تعالى بقوله:\n﴿إِنَّ ٱللَّهَ ٱشۡتَرَىٰ مِنَ ٱلۡمُؤۡمِنِينَ أَنفُسَهُمۡ وَأَمۡوَٰلَهُم بِأَنَّ لَهُمُ ٱلۡجَنَّةَۚ﴾⟪9:111⟫، الآية، وبقوله: ﴿وَأَحۡسِنُوٓاْۚ إِنَّ ٱللَّهَ يُحِبُّ ٱلۡمُحۡسِنِينَ﴾⟪2:195⟫، أي تحروا فعل الإحسان وقد تقدم أن الإحسان هو تحري العدالة والزيادة عليها، ولهذا قال:\n﴿إِنَّ ٱللَّهَ يَأۡمُرُ بِٱلۡعَدۡلِ وَٱلۡإِحۡسَٰنِ﴾⟪16:90⟫، ثم نبه بإظهار محبته للمحسنين على شرف منزلتهم.\n⟦1:412⟧"}, {"a": [196], "v": 1, "p": 412, "ev": 1, "ep": 416, "sid": 413, "t": "قوله - عز وجل:\n﴿وَأَتِمُّواْ ٱلۡحَجَّ وَٱلۡعُمۡرَةَ لِلَّهِۚ فَإِنۡ أُحۡصِرۡتُمۡ فَمَا ٱسۡتَيۡسَرَ مِنَ ٱلۡهَدۡيِۖ وَلَا تَحۡلِقُواْ رُءُوسَكُمۡ حَتَّىٰ يَبۡلُغَ ٱلۡهَدۡيُ مَحِلَّهُۥۚ فَمَن كَانَ مِنكُم مَّرِيضًا أَوۡ بِهِۦٓ أَذٗى مِّن رَّأۡسِهِۦ فَفِدۡيَةٞ مِّن صِيَامٍ أَوۡ صَدَقَةٍ أَوۡ نُسُكٖۚ فَإِذَآ أَمِنتُمۡ فَمَن تَمَتَّعَ بِٱلۡعُمۡرَةِ إِلَى ٱلۡحَجِّ فَمَا ٱسۡتَيۡسَرَ مِنَ ٱلۡهَدۡيِۚ فَمَن لَّمۡ يَجِدۡ فَصِيَامُ ثَلَٰثَةِ أَيَّامٖ فِي ٱلۡحَجِّ وَسَبۡعَةٍ إِذَا رَجَعۡتُمۡۗ تِلۡكَ عَشَرَةٞ كَامِلَةٞۗ ذَٰلِكَ لِمَن لَّمۡ يَكُنۡ أَهۡلُهُۥ حَاضِرِي ٱلۡمَسۡجِدِ ٱلۡحَرَامِۚ وَٱتَّقُواْ ٱللَّهَ وَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ﴾⟪2:196⟫\n\" الآية (196) سورة البقرة \".\nقيل: قوله: ﴿وَأَتِمُّواْ﴾⟪2:196⟫ قيل إنه خطاب لمن خرج حاجا أو معتمرا، فأمر بأن لا يصرف وجهه حتى يقضيها، وإليه ذهب أبو حنيفة - رحمه الله - فاحتج به في وجوب إتمام كل عبادة دخل فيها [لإنسان] متنفلا، وأنه متى أفسدها وجب قضاؤها وقيل إنه خطاب لهم ولمن لم يتلبس بالعبادة وذكر لفظ الأيام تنبيه على توفية حقهما وإكمال شرائطها، ولذلك قال أمير المؤمنين:\n\" من إتمامهما أن تحرم بهما من دويرة أهلك \" وعلى هذا قوله: ﴿ثُمَّ أَتِمُّواْ ٱلصِّيَامَ إِلَى ٱلَّيۡلِۚ﴾⟪2:187⟫، وإلى هذا ذهب الشافعي - رحمه الله واحتج به في وجوب العمرة، وإنما قال في الحج والعمرة \" لله \" ولم يقل ذلك في الصلاة والزكاة من أجل أنهم كانوا يتقربون ببعض أفعال الحج والعمرة إلى الأصنام، فخصهما بالذكر لله تعالى حثا على الإخلاص فيهما ومجانبة ذلك الاعتقاد المحظور، وظاهر قوله: ﴿فَإِنۡ أُحۡصِرۡتُمۡ﴾⟪2:196⟫ أن لا فرق بين أن يحصر بمكة أو بغيرها، وبعد عرفة أو قبلها بخلاف ما قال أبو حنيفة إن من أحصر بمكة أو بعد الوقوف لا يكون محصرا في الحكم، وكذلك لا فرق في [الظاهرة] بين أن يحصره عدو مسلم أو كافر كما قال الشافعي خلافا لبعضهم، وظاهره يقتضي أن\n⟦1:413⟧\nلا فصل بين إحصار العدد وإحصار المرض كما قال أبو حنيفة دون الشافعي - رحمة الله عليهما - \" لولا أن الآية نزلت في سبب العدو فلا يجوز أن نتعدى إلا بدلالة \"، ولأن قوله: ﴿فَإِذَآ أَمِنتُمۡ﴾⟪2:196⟫ يدل على أن المراد بالإحصار هو بالعدو وذلك قول ابن عباس - رضي الله عنه - ويقتضي الظاهر أن لا قضاء عليه خلافا لأبي حنيفة - رضي الله عنه - لأنه قال: ﴿فَمَا ٱسۡتَيۡسَرَ مِنَ ٱلۡهَدۡيِۖ﴾⟪2:196⟫ واقتصر عليه والهدي بقرة أو بدنة أو شاة أو أكثر، لأنه قال: ﴿فَمَا ٱسۡتَيۡسَرَ﴾⟪2:196⟫، ونهى عن حلق الرأس إلا بعد بلوغ الهدي محله، ومحله عند أبي حنيفة الحرم، واستدل بأن ناجية بن جندب قال: \" دعني أخذ بعض هذه الأودية، وأسوق هذه البدن إلى الحرم، فأنحر بها \"، فقال - عليه السلام -: \" افعل \" فساقها إلى الحرم، فنحر بها، وعند الشافعي أن محل الهدي في الإحصار زمان تحلله، ومنحر الهدي حيث يتحلل، وقوله تعالى: ﴿فَمَن كَانَ مِنكُم مَّرِيضًا﴾⟪2:196⟫ ليس مقصورا على المحصر، بل حكم كل حاج ومعتمر، والمرض الذي يبيح اللبس والحلق ويقتضي الفدية هو الذي يحتاج إلى تغطية البدن وحلق الشعر، وألزم فدية على التخيير ولم يبين وصفها، فنبه عليه النبي - صلى الله عليه وسلم - بقوله لكعب بن عجرة وقد مر به يوم الحديبية وهو محرم، فقال له: \" أيؤذيك هو أم رأسك؟ فقال: نعم، فقال: نعم فقال: احلق رأسك واذبح نسيكة، أو صم ثلاثة أيام أو أطعم ستة مساكين بين كل مسكين صاع \"، وظاهر الآية يقتضي أن لا فرق بين قليل الشعر وكثيرة بخلاف ما قال أبو حنيفة حين لم يلزم إلا بحلق الثلث، وغيره حين لم يلزم إلا بالربع، وأما التمتع بالعمرة إلى الحج، فقد قيل هو المحصر إذا دخل مكة بكد فوت الحج، وقيل: \" هو الناسخ الحج بالعمرة \"، وقيل: هو التمتع المعروف في الحج، وهو الأصح ولا يجب الدم فيه إلا أن يكون بأربع شرائط، الأول: الإحرام بالعمرة في أشهر الحج والتحلل منها فيه، والثاني: أن ينسئ الحج من سنته، والثالث: أن لا يعود إلى الميقات لإنساء الحج، والرابع: أن لا يكون من حاضري الحرم، وإن أحرم في رمضان وأخر الطواف إلى شوال ثم أحرم بالحج فهل يلزمه الدم؟\nفيه قولان للشافعي، وظاهر إيجاب ما استيسر من الهدى يقتضي أن ذلك بعد الفراغ من\n⟦1:414⟧\nالعمرة والدخول في الحج، وكذا الصوم الذي هو بدله وعند أبي حنيفة يجوز الصوم إذا دخل في العمرة ناويا للتمتع ..\nإن قيل: كيف قال في الحج ومهما أحرم يوم عرفة لا يمكنه صيام ثلاثة أيام في الحج، لأنة منهي عن الصوم في يوم النحر وأيام التشريق؟ قيل: الواجب على المتمتع أن يحرم بالحج على الوجه عليه صيام ثلاثة أيام، وذلك بتقديم الإحرام قبل يوم عرفة، وقد قال ابن عمر وعائشة: يصوم أيام التشريق، ويحملان النهي عن الصوم فيها على غير المتمتع وقوله: «إذا رجعتم إلى بلدكم» [قيل: معناه إذا أخذتم في الرجوع] بعد الفراغ وقيل: ﴿إِذَا رَجَعۡتُمۡۗ﴾⟪2:196⟫ إلى بلدكم [وأهليكم] وإطلاق اللفظ يحتمل الأمرين جميعا، فيصح حمله عليهما، وحاضروا المسجد الحرام، قال عطاء: هم أهل الحرم والقربات التي حوله ما لم تبلغ مسافة تقصر فيها الصلاة وبه قال الشافعي وقال طاوس: أهل الحرم لا غير وقال أبو حنيفة: هم أهل المواقيت وما دونها، وقوله تعالى: (ذلك) أي الكفارة لمن لم يكن حاضري المسجد، فأما حاضروا المسجد، فلا يلزمهم، وقيل: عني بذلك التمتع أي أن الحاضرين ليس لهم أن يتمتعوا وإنما ذلك لأهل الآفاق البعيدة.\nإن قيل: ما الحاجة إلى ذكر: \" تلك عشرة كاملة \" عقب قوله (سبعة، وثلاثة، ولا يشك على ذي أدنى بصيرة أن الثلاثة والسبعة عشرة) ولا أن ذلك يتنوع، فيكون مرة كاملة ومرة غير كاملة، لأنها إذا لم تكن كاملة لم تكن عشرة؟\nقيل: قد أجيب عن ذلك بأجوبة ..\nالأول: أنه لما قال: ﴿ثَلَٰثَةِ أَيَّامٖ فِي ٱلۡحَجِّ وَسَبۡعَةٍ إِذَا رَجَعۡتُمۡۗ﴾⟪2:196⟫ كان يحتمل التخيير، وأن كل واحد منهما على الانفراد يقوم مقام الهدي فبين أن مجموعهما يدل على الهدي يقوم مقامه، والثاني: أنه\n⟦1:415⟧\nلما قصد بيان كمال الحكم، وأن ذلك يحصل في صوم العشرة، ذكر لفظ العشرة تأكيدا، فإن كان لو قال: (تلك كاملة) كانت مفهومة، وذاك أن الخطاب العامي، أعني ما يفهم به الخاص والعام الذين هم أهل الطبع لا أهل الارتياض بالتعلم لا يكون إلا تكريرات الكلام وزيادات البيان ليحسن إفهام الكافة، ولهذا جاء على القرآن عاما ما يتعلق حكمه بالكافة في غاية الظهور، وما هو مختص علمه بالراسخين في العلم جاء على ضرب من الإيجاز والغموض، إذ كانوا بمعرفتهم يمكنهم أن يتوصلوا إلى حقائقه، وما هو متردد بين العامة والخاصة كذكر التوحيد والنبوة ذكر تارة بلفظ مبسوط، ليظهر منه للعامة ما يفتعهم، وتارة بالفظ وجيز ليستخرج منة الخاصة ما يتضمنه، ولهذا قال فيما يغمض، ﴿وَلَوۡ رَدُّوهُ إِلَى ٱلرَّسُولِ وَإِلَىٰٓ أُوْلِي ٱلۡأَمۡرِ مِنۡهُمۡ﴾⟪4:83⟫، والثالث: أن قوله: ﴿تِلۡكَ عَشَرَةٞ كَامِلَةٞۗ﴾⟪2:196⟫ استطراد كلام، وتنبيه على فضيلة علم العدد، وذاك أنه قد قيل: العدد أول العلوم وأشرفها، أما كونه أولا، فلأن ما عداه به تميز وتفضل، وأما كونه أشرف، فلأنه لا اختلاف فيه ولا تغيير، بل هو لازم طريقة واحدة، فذكر العشرة، وصفها بالكاملة، إذ هي عدد كمل فيه خواص الأعداد فإن الواحد مبدأ العدد، والاثنين أول العدد، والثلاثة أول عدد فرد، والأربعة أول عدد زوج محدود، أي مجتمع من ضرب عدد في نفسه، والخمسة أول عدد دائر، والستة أول عدد تام، أي إذا أخذت أجزاؤه لم يزد عليه ولم ينقص منه، والسبعة أول عدد أول أي لا يتقدمه عدد بعده، والثمانية أول عدد زوج الزوج والتسعة أول عدد مثلث، والعشرة أول عقد ينتهي إليه العدد، فإن كل عدد بعده مكرر منه بما قبله، فإذن العشرة هي العدد الكامل ..\n⟦1:416⟧"}, {"a": [197], "v": 1, "p": 416, "ev": 1, "ep": 419, "sid": 417, "t": "قوله - عز وجل -:\n﴿ٱلۡحَجُّ أَشۡهُرٞ مَّعۡلُومَٰتٞۚ فَمَن فَرَضَ فِيهِنَّ ٱلۡحَجَّ فَلَا رَفَثَ وَلَا فُسُوقَ وَلَا جِدَالَ فِي ٱلۡحَجِّۗ وَمَا تَفۡعَلُواْ مِنۡ خَيۡرٖ يَعۡلَمۡهُ ٱللَّهُۗ وَتَزَوَّدُواْ فَإِنَّ خَيۡرَ ٱلزَّادِ ٱلتَّقۡوَىٰۖ وَٱتَّقُونِ يَٰٓأُوْلِي ٱلۡأَلۡبَٰبِ﴾⟪2:197⟫\nالآية: (197) سورة البقرة.\nجدل الحبل فتله، وبه سمي الزمام جديلا، وعنه استعبر \" جالت فلانا \"، ولذلك قيل: ناقضه تشبيها بنقض الحبل، وقتل فلان، يفتل حبلا \"، في ذورة فلان، إذا أحتال عليه، والجدول: النهر الممتد كالحبل المفتول، والمجدل: القصر المحكم، والجذالة: كل أرض صلبة، والزاد: فضل الطعام الزائد عما يكتفي به في الوقت، وقد بين الله تعالي فيما تقدم أحكام الحج وما يقع فيه من الإحصار [واستباحة] الحلق والتمتع، وبين في هذه الآية وقته الذي يصح فيه ذلك، ومن قال: أشهر الحج: شوال، وذو القعدة، وتسع من ذي الحج عنى أن فعله يقع في هذه المدة، لأن لفظ الأشهر يقع على الاثنين، وبعض الثالث، فالفعل قد ينسب إلى مدة ممتدة ويكون واقعا في بعضها، ولما كان فعل الحج في هذه الأشهر نسب إليها ثلاثتهن، ودلت الآية على أن الإحرام بالحج في غيرهن لا يصح لتخصيص الأشهر وهي أدنى العدد، ولقوله:\n﴿فَمَن فَرَضَ فِيهِنَّ ٱلۡحَجَّ﴾⟪2:197⟫، والضمير على هدا الوجه لا يقال في التواريخ إلا لأدنى العدد، كقوله: ﴿إِنَّ عِدَّةَ ٱلشُّهُورِ عِندَ ٱللَّهِ ٱثۡنَا عَشَرَ شَهۡرٗا﴾⟪9:36⟫، ثم قال: ﴿أَرۡبَعَةٌ حُرُمٞۚ﴾⟪9:36⟫، ثم قال: ﴿فَلَا تَظۡلِمُواْ فِيهِنَّ﴾⟪9:36⟫ [يعني: في الأربعة الحرم،] ويقال: لثلاث خلون، وثلاث عشر خلت، وقول مالك: إن الإحرام بالحج يصح بعد يوم العاشر بالحج مستدلا بظاهر الآية قوي، ويعاضده ما روي عنه- عليه\n⟦1:417⟧\nالسلام- \" أشهر الحج شوال، وذو القعدة، وذو الحجة \"، وقوله: ﴿فَمَن فَرَضَ فِيهِنَّ ٱلۡحَجَّ﴾⟪2:197⟫ أي التزم حكمه، وذلك عند الشافعي بالنية فقط وبها يصير محرما عنده وعند أبي حنيفة- رحمه ألفة بالنية، ومع سوق الهدى أو التلبية، [واستعمل الفرض في] والتزام الحكم وأصله من قطع الحكم مأخوذا من \" قرض القوس \" أي: حزه، وقيل لثعلب النحوي: لم جعل الغرض لما في أوكد والنية لمآ هو أخف؟\nقال: لأن الفرض لما يؤثر، كفرض الزند والقوس والسن للضب، فلما كان تأثير الفرض في نفس الشك أبلغ من تأثير السن، فجعل لما هو أوكد والرفث ههنا: قيل هو الجماع، وقيل: هو حديث الجماع، وروي عن ابن عباس- رضي الله عنه- أنه كان ينشد في الطواف:\nإن تصدق الطير ننك لميسا ...\nفقيل له: أترفث؟\nفقال: \" ليس هذا الرفث، إنما الرفث مراجعة النساء الحديث بذكر الجماع \"،\nإن قيل: الفسوق محظور في كل حال، فكيف خص به الحج؟ قيل: الفسوق هاهنا يعني الأشياء المحظور تعاطيها في حال، [الحج] كالصيد والطيب، واللباس، وإن لم ليكون فسقا في غير الحج؟ قيل: تخصيص الحج به تنبيه على شرفه وعظم موقعه، كقوله: ﴿فَلَا تَظۡلِمُواْ فِيهِنَّ أَنفُسَكُمۡۚ﴾⟪9:36⟫ وإن كان ظلم النفس في كل حال\n⟦1:418⟧\nمكروها، وكما قال: \" إذا صام أحدكم فلا يجهل، فلا يرفث، فإن جهل عليه فليقل: إني صائم \"، وقوله ﴿وَلَا جِدَالَ﴾⟪2:197⟫ أي: لا يجوز المماراة، وقيل معناه: لا شك أن فرضه مقرر في ذي الحجة بخلاف ما فكله النساءة، قيل: هو حث على التحاب وقيل: \" هو حث على التحاب والنظافة وترك ما يؤدي إلى التباغض \"، وكل ذلك يصح إرادته، وقيل قوله: ﴿فَلَا رَفَثَ وَلَا فُسُوقَ﴾⟪2:197⟫ إشارة إلى أن من التزم هذا الفرض وتحراه يمنعه عن الرفث والفسوق، وكأنه نبه على علة ما أوجه لأجله الحج، فهو تهذيب اللسان عن الخنا، وإصلاح البدن [بالمنع] من تعاطي الفسق، كما جعل الصلاة علة لترك الفحشاء والمنكر، والصوم علة للتقوى في قوله: ﴿لَعَلَّكُمۡ تَتَّقُونَ﴾، والزكاة علة لتزكية النفس في قوله: ﴿وَتُزَكِّيهِم بِهَا﴾⟪9:103⟫ وقوله: ﴿وَلَا جِدَالَ﴾⟪2:197⟫ نهي على ما تقدم، ولهذا فضل بين إعرابيهما بعض القراء، ونبه بقوله: ﴿وَمَا تَفۡعَلُواْ مِنۡ خَيۡرٖ يَعۡلَمۡهُ ٱللَّهُۗ﴾⟪2:197⟫ على مجاراته إياهم، كما نبه في عامة القراء على ذلك، نحو: ﴿سَمِيعٌ عَلِيمٞ﴾، ﴿وَٱللَّهُ يَعۡلَمُ ٱلۡمُفۡسِدَ مِنَ ٱلۡمُصۡلِحِۚ﴾⟪2:220⟫، و ﴿إِنَّ رَبَّكَ لَبِٱلۡمِرۡصَادِ﴾⟪89:14⟫ وما يجري مجراه من الأقوال:\nوقوله: ﴿وَتَزَوَّدُواْ فَإِنَّ خَيۡرَ ٱلزَّادِ ٱلتَّقۡوَىٰۖ﴾⟪2:197⟫ حث على تقوى الله واقتناء الأعمال الصالحة، والإعراض عن الدنيا سوى ما يتوصل به إلي الآخرة ...\n، وقال أبو المطيع البلخي لحاتم الأصم:\n\" بلغني أنك تجوب ألبادية بلا زاد فقال: إنهم أجوبها بأربعة أشياء، أرى الدنيا بحذافيرها ملكا لله ، وأرى الخلق كلهم عبيدا لله، وأرى الأشياء كلها بيده، وأرى قضاءه نافذا في كل أرض \"،، فقال: \" نعم الزاد زادك يا حاتم نحوت فيما مفاوز ألآخرة \"، وقول من قال: \" أنزلت الآية في قوم يحجون بلا\n⟦1:419⟧\nزاد، ويتكففون، فنهوه عن ذلك، فلا يمتنع أن يكون مراد بالآية مما تقدم، فالتكفف قل يكون منافيا للتقوى \"، وقوله: ﴿وَٱتَّقُونِ يَٰٓأُوْلِي ٱلۡأَلۡبَٰبِ﴾⟪2:197⟫ لما أمر بالتقوى، أمر أن يكون هو تعالى المقصود بها، وقيل: تقواه حفظ النفس إن نالها عقابه أو يتخطاها ثوابه، وذلك منعها متابعة الهوى، وحملها على طريق الهدى، وذلك على ثلاثة منازل ...\nالأول: ترك الكفر والكبائر، والثاني: ترك المحارم وأداء الفرائض اللذين يقتضيهما إلتزام الشرائع، والثالث: حفظ القلوب عن التلفت إلى الذنوب، وهو المغنى، بقول من قال: \" التقوى هي التبرؤ من كل شك سوى الله تعالي، ولا يحصل الثالث إلا بحصول الثاني، ولا الثاني إلا بحصول الأول \"، وعنى هاهنا الغاية، ولهذا خص أولوا الألباب بالخطاب، فاللب أشرف أوصاف العقل، وهو اسم الجزء الذي بإضافته إلى سائر أجزاء الإنسان، كلب الشيء إلى القشور، وباعتبار اللب، قيل لضعيف العقلي \" يراعة \"، \" وقصبة \"، و \" منخوب \" و \" خاوي الصدر \"، وقال- عز\nوجل- ﴿وَأَفۡـِٔدَتُهُمۡ هَوَآءٞ﴾⟪14:43⟫، وقال تعالى: ﴿وَأَصۡبَحَ فُؤَادُ أُمِّ مُوسَىٰ فَٰرِغًاۖ﴾⟪28:10⟫."}, {"a": [198], "v": 1, "p": 419, "ev": 1, "ep": 421, "sid": 420, "t": "قوله - عز وجل -:\n﴿لَيۡسَ عَلَيۡكُمۡ جُنَاحٌ أَن تَبۡتَغُواْ فَضۡلٗا مِّن رَّبِّكُمۡۚ فَإِذَآ أَفَضۡتُم مِّنۡ عَرَفَٰتٖ فَٱذۡكُرُواْ ٱللَّهَ عِندَ ٱلۡمَشۡعَرِ ٱلۡحَرَامِۖ وَٱذۡكُرُوهُ كَمَا هَدَىٰكُمۡ وَإِن كُنتُم مِّن قَبۡلِهِۦ لَمِنَ ٱلضَّآلِّينَ﴾⟪2:198⟫\nالآية (198) - سورة البقرة.\nفاض الإناء، انصب عن امتلاء ومنه: فاض صدره بسره، ورجل فياض سخي- تشبيها بنهر فياض، ودرع مفوضة: افتضت على لابسها كقولهم: مسنونة، وعنه استعير: \" أفاض من عرفة \"، و \" أفاض بالقداح \" و \" أفاض البعير بحريه \"، و \" حديث مستفيض \"، كقولهم: شائع وسائر، وكانت العرب تتحاشى من التجارة في الحج حتى إنهم كانوا يتجنبون المبايعة إذا دخل العشر الأواخر، وحتى سموا\n⟦1:420⟧\nمن يوالي متجرا في الحج: الداج دون الحاج، فأباح الله ذلك، وعلى إباحة ذلك دل قوله: ﴿وَأَذِّن فِي ٱلنَّاسِ بِٱلۡحَجِّ﴾⟪22:27⟫ إلى قوله: ﴿لِّيَشۡهَدُواْ مَنَٰفِعَ لَهُمۡ﴾⟪22:28⟫، وقوله: ﴿وَءَاخَرُونَ يَضۡرِبُونَ فِي ٱلۡأَرۡضِ يَبۡتَغُونَ مِن فَضۡلِ ٱللَّهِ﴾⟪73:20⟫، وأمر الله بذكر الله تعالى عند المشعر الحرام أي المزدلفة، وقيل: عنى بذكره عند الجمع بين المغرب والعشاء، وهذا يدخل في عموم الذكر، فقد سمي الصلاة ذكرا في قوله ﴿فَٱسۡعَوۡاْ إِلَىٰ ذِكۡرِ ٱللَّهِ﴾⟪62:9⟫ وقيل لبعض العلماء: \" لم أمر الناس بالمقام عند المشعر الحرام، وبالذكر؟، فقال: لأن الكعبة بيت الله الحرام حجابه، والشعر بابه، والوافد إذا قصد الباب أقام وتضرع، فإذا وصل إلى الحجاب، قدم قربانات، وقضى التفث، وتطهر، ثم يؤذن له في الدخول، وأعاد الأمر بالذكر ثانيا، وأوجب أن يكون ذكره كهدايته أي مولدا لهدايته لنا ثم قال: ﴿وَإِن كُنتُم﴾⟪2:198⟫، أي وإنكم كنتم قبل لضالين، وإن محققة من الثقيلة بدلالة- دخول اللام معها، والضلال هاهنا الجهل بالمعارف الحقيقية نحو: ﴿وَوَجَدَكَ ضَآلّٗا فَهَدَىٰ﴾⟪93:7⟫.\n⟦1:421⟧"}, {"a": [199], "v": 1, "p": 421, "ev": 1, "ep": 423, "sid": 422, "t": "قوله - عز وجل -:\n﴿ثُمَّ أَفِيضُواْ مِنۡ حَيۡثُ أَفَاضَ ٱلنَّاسُ وَٱسۡتَغۡفِرُواْ ٱللَّهَۚ إِنَّ ٱللَّهَ غَفُورٞ رَّحِيمٞ﴾⟪2:199⟫\nالآية: (199) - سورة البقرة.\nروي أن قريشا لم يكونا يقفون مع الناس بعرفة ولا يبيتون بالمزدلفة ويقولون: \" نحن أهل حرم الله \"، وكانوا يقفون دون عرفة فأمرهم الله تعالى أن يفيضوا مع سائر الناس، قاله ابن عباس، وعائشة، ومجاهد، والحسن، وقيل: إنه أمر جميع الناس أن يفيضوا من حيث أفاض الناس، أي إبراهيم، وسماه \" الناس \" والناس تستعمل على ضربين، أحدهما: للنوع من غير اعتبار مدح أو ذم،\nوالثاني: للمدح اعتبارا بموجود تمام الصورة المختصة بالإنسانية، وليس ذلك في هذه اللفظة فقط، بل في اسم كل جنس ونوع، نحو: هذا فرس، وفلان رجل، وليس هذا بفرس ولا فلان برجل، أي ليس فيه معناه الخاص بنوعه، وبهذا النظر نفى السمع والبصر عن الكفار، فعلى هذا سمى إبراهيم الناس على سبيل المدح [على وجه أخر] وهو أن الواحد يسمى باسم الجماعة تنبيها أنه يقوم مقامهم في الحكم، وعلى هذا قول الشاعر:\nويرى فيحسبه القتيل قتيلا ...\nوقال: تستجمعي الخلق في تمثال إنسان\n⟦1:422⟧\nوقال: وليس من الله بمستنكر ...\nأن يجمع العالم في واحد\nوعلى هذا قال تعالي: ﴿إِنَّ إِبۡرَٰهِيمَ كَانَ أُمَّةٗ﴾⟪16:120⟫، وقوله: ﴿مِنۡ حَيۡثُ﴾⟪2:199⟫ أي من عرفة، وقيل: من المزدلفة، وهو أقرب، لأن بعده: ﴿فَإِذَآ أَفَضۡتُم مِّنۡ عَرَفَٰتٖ﴾⟪2:198⟫، والاستغفار، والتوبة، والإنابة، والأوبة تتقارب، لكن الاستغفار [طلب] غفر الذنب، والتوبة تركه، والإنابة: الرجوع عن الضلال إلى الهدى، والأوبة رجوع القلب إلي الله تعالى، وهذه المعاني وإن كانت متلازمة، فألفاظها اختلفت\nلاختلاف النظرات، فأمر تعالى بالاستغفار له عن الاشتغال بغيره من أمور الدنيا، وبين أن الله تعالى غفور للمطيعين، رحيم بالعاصين، يدعوهم برحمته إلي بابه، ويرغبهم في جزيل ثوابه ...\n⟦1:423⟧"}, {"a": [200], "v": 1, "p": 423, "ev": 1, "ep": 425, "sid": 424, "t": "قوله - عز وجل -:\n﴿فَإِذَا قَضَيۡتُم مَّنَٰسِكَكُمۡ فَٱذۡكُرُواْ ٱللَّهَ كَذِكۡرِكُمۡ ءَابَآءَكُمۡ أَوۡ أَشَدَّ ذِكۡرٗاۗ فَمِنَ ٱلنَّاسِ مَن يَقُولُ رَبَّنَآ ءَاتِنَا فِي ٱلدُّنۡيَا وَمَا لَهُۥ فِي ٱلۡأٓخِرَةِ مِنۡ خَلَٰقٖ﴾⟪2:200⟫\nالآية (200) - سورة البقرة.\nالقضاء: فصل الأمر، والنسك أخذ النفس ببلوغ غاية العبادة، واختص في تعارف أهل الفقه بعمل الحج وبالذبيحة حتى سميت نسيكة، كما سميت قربانا، وقولهم: إذا فعلت كذا فافعل كذا، يقال على ثلاثة أوجه:\nالأول: أن يكون \" افعل \" أمرا بما تقدم فعله نحو، ﴿إِذَا قُمۡتُمۡ إِلَى ٱلصَّلَوٰةِ فَٱغۡسِلُواْ﴾⟪5:6⟫ الثاني: أن يكون الأمر بشيء هو من أبعاض ذلك الفعل وفي أثنائه، نحو: \" إذا صليت فاركع واسجد \"، والثالث: أن يكون بعده، نحو: ﴿فَإِذَا قُضِيَتِ ٱلصَّلَوٰةُ فَٱنتَشِرُواْ﴾⟪62:10⟫ والآية، محمولة على ذلك تنبيها ففي ابتداء النسك ذكر، وهو التلبية وفي أثنائه ذكر، وهو عند المشعر والطواف، وفي انتهائه ذكر، وهو شكر الله- عز وجل- وذكره عند طواف الوداع، ولما كان الذكر ذكرين، ذكر بالقلب، وذكر باللسان تتناولهما الآية، ولما كان الإنسان لا يتشكك في أن أباه أحد أسباب وجوده، وأنه منه أوجد ولا ينسى ذكره في شيء من أحواله، وكانوا يتبجحون بمكانه، ويفتخرون بكونهم عنه، أمروا أن يذكروا الله كذكرهم آباءهم وأن يتحققوا أنه تعالى سبب وجودهما، بل سبب وجود آبائهم، وأن يفتخروا به كافتخارهم بآبائهم، وقد روي أنهم كانوا يفتخرون بأبائهم بعد فراغهم من حجهم، فأبطل الله ذلك، وعليه نبه النبي ...\nبقوله: \" إن الله تعالى أذهب عنكم نخوة الجاهلية وتعظيمها بالآباء، فالناس من آدم، وآدم من تراب، ولا فضل\nلعربي على عجمي إلا بالتقوى \"، ثم تلا قول الله تعالى: ﴿يَٰٓأَيُّهَا ٱلنَّاسُ إِنَّا خَلَقۡنَٰكُم مِّن ذَكَرٖ وَأُنثَىٰ وَجَعَلۡنَٰكُمۡ شُعُوبٗا وَقَبَآئِلَ لِتَعَارَفُوٓاْۚ إِنَّ أَكۡرَمَكُمۡ عِندَ ٱللَّهِ أَتۡقَىٰكُمۡۚ﴾⟪49:13⟫ ...\n⟦1:424⟧\nوقوله: ﴿أَوۡ أَشَدَّ ذِكۡرٗاۗ﴾⟪2:200⟫ تنبيه أنه إذا كان الأب يذكر لأنه سبب ما لوجودكم، فالباري- عز وجل- أولى بأن يذكر ..\nإن قيل: كيف خير بين أن يذكر كل كر الآباء وبين أن يذكر أشده ذكرا؟\nقيل: لفظ أو وإن كان للتخيير، فمقتضى الكلام على إيجاب أن يكون ذكره أشد، لأنه لما نبه علي موضع نعمتهما أعنى نعمة الأب ونعمة الله- عز وجل- وشكر المنعم بقدر عظمة نعمته، وقد علم فضل نعمته تعالى على فضل نعمة الأب، فصار ذلك منبها أن ذكر الله أوجب وقوله:\n﴿مَن يَقُولُ رَبَّنَآ﴾⟪2:200⟫ إشارة إلى ما روي أنهم كانوا يقولون: \" اللهم أكثر مالنا، وأولادنا وأنزل الغيث علينا، وأنبت مرعانا \"، ولا يسألون شيئا من أمور أخرجهم، وإنما سألوه الدنيا دون الآخرة، لأنهم عرفوها ولم يعرفوا اللآخرة، وكيف يسال الآخرة من لا يعرفها؟، وكيف يعرفها من لم يتحقق كونها؟، وكيف يتحقق كونها من لم يبصرها؟ أي لم تدركها بصيرته؟ وليس يعني بقوله: (يقول) التفوه بذلك فقط، بل صرف العناية إليها والاهتمام بها، والخلاق نصيب الإنسان من أفعاله المحمودة التي تكون خلقا له، وذلك أن الفعل قد يحصل من الإنسان تخلفا، وقد يحصل منه خلقا وهو المحمود، وفي قوله: ﴿وَمَا لَهُۥ فِي ٱلۡأٓخِرَةِ مِنۡ خَلَٰقٖ﴾⟪2:200⟫ تنبية أن الأريحية لهم صادقة صادرة عن أخلاقهم ..\n⟦1:425⟧"}, {"a": [201], "v": 1, "p": 425, "ev": 1, "ep": 425, "sid": 426, "t": "قوله - عز وجل -:\n﴿وَمِنۡهُم مَّن يَقُولُ رَبَّنَآ ءَاتِنَا فِي ٱلدُّنۡيَا حَسَنَةٗ وَفِي ٱلۡأٓخِرَةِ حَسَنَةٗ وَقِنَا عَذَابَ ٱلنَّارِ﴾⟪2:201⟫\nالآية (201) - سورة البقرة.\nلما أجرى الله تعالى العادة أن لابد للإنسان من أخيارهم وأشرارهم من بلغه في الدنيا، صار المؤمن يطلبها كما يطلبها الكافر، لكان طلب المؤمن لها علي سبيل الغرض قدر ما يحس، وفي وقت ما يحسن، ولأجل الحاجة إليها ..\nقال بعض الصالحين: \" اللهم وسع الدنيا علي، وزهذني فيها، ولا تضيقها علي فترغبني فيها \".\nفقوله تعالى: ﴿ءَاتِنَا فِي ٱلدُّنۡيَا حَسَنَةٗ﴾⟪2:201⟫ أي مالا يستقبح عاجلا وأجلى ويكون ذريعة إلى المقصد، ﴿وَفِي ٱلۡأٓخِرَةِ حَسَنَةٗ﴾⟪2:201⟫ أي ثوابا ورحمة وعلى هذا قال الحسن الحسنة في الدنيا العلم والعبادة، وفي الآخرة: الجنة ﴿وَقِنَا عَذَابَ ٱلنَّارِ﴾⟪2:201⟫ أي: احفظنا من الشهوات والذنوب المؤدية إلى النار."}, {"a": [202], "v": 1, "p": 425, "ev": 1, "ep": 426, "sid": 426, "t": "قوله- عز وجل -:\n﴿أُوْلَٰٓئِكَ لَهُمۡ نَصِيبٞ مِّمَّا كَسَبُواْۚ وَٱللَّهُ سَرِيعُ ٱلۡحِسَابِ﴾⟪2:202⟫\nالآية: (202) - سورة البقرة.\nالنصيب في الأصل: المنصوب، وجعل السهم المقرر نصيبا، والنصب: رفع الشح، وبه سمي النصب، وإنصاب الحرم، ونصاب السكين، وفلان في نصاب صدق تشبيها بنصاب السكين، ونسب الحروف في الإعراب، ونصب الستر على التشبيه، والحساب: عنه استعير الحسبان المقارب لمعنى الظن، وحسب الذي هو معنى الكفاية بين تعالى أن من جمع بين طلب دنياه وأخراه، ولم يقتصر على طلب الدنيا الموصوفة.\nبقوله تعالى: ﴿إِنَّمَا مَثَلُ ٱلۡحَيَوٰةِ ٱلدُّنۡيَا كَمَآءٍ أَنزَلۡنَٰهُ مِنَ ٱلسَّمَآءِ﴾⟪10:24⟫ الآية، فقد تناول نصيبه المأمور به في قوله: ﴿وَلَا تَنسَ نَصِيبَكَ مِنَ ٱلدُّنۡيَاۖ﴾⟪28:77⟫، ولم يكن كمن قال فيهم:\n⟦1:426⟧\n﴿وَقَدِمۡنَآ إِلَىٰ مَا عَمِلُواْ مِنۡ عَمَلٖ فَجَعَلۡنَٰهُ هَبَآءٗ مَّنثُورًا﴾⟪25:23⟫، ولما كان الحساب يكشف عن مجمل الشيء وتفصيله، نبه بذلك على إحاطته بأفعال عباده ووقوفه على حقائقها، وذكر \" السريع \" تنبيها أن ذلك منه، لا في زمان ولا بفكره، وذلك أبلغ ما يمكن أن يتصور به الكافة سرعة فعل الله عز وجل."}, {"a": [203], "v": 1, "p": 426, "ev": 1, "ep": 427, "sid": 427, "t": "قوله- عز وجل -:\n﴿وَٱذۡكُرُواْ ٱللَّهَ فِيٓ أَيَّامٖ مَّعۡدُودَٰتٖۚ فَمَن تَعَجَّلَ فِي يَوۡمَيۡنِ فَلَآ إِثۡمَ عَلَيۡهِ وَمَن تَأَخَّرَ فَلَآ إِثۡمَ عَلَيۡهِۖ لِمَنِ ٱتَّقَىٰۗ وَٱتَّقُواْ ٱللَّهَ وَٱعۡلَمُوٓاْ أَنَّكُمۡ إِلَيۡهِ تُحۡشَرُونَ﴾⟪2:203⟫\nالآية (203) - سورة البقرة.\nالأيام المعدودات عند الشافعي- رحمه الله- ثلاثة أيام بعد النخر، والمعلومات عشر ذي الحجة، وقال مالك وأبو حنيفة رحمهما الله- في إحدى الروايتين: المعدودات يوم النحر، ويومان بعده، فيوم النحر عندهما من المعلومات ومن المعدودات جميعا، وقائمة الخلاف أن عند مالك لا يجوز النحر ثالث أيام التشريق والحشر: ضم المتفرق وسوقه، يقال: حشرتهم السنة: أي ضمتهم من النواحي إلى الحضر، واختص حشرات الأرض بصغار الدواب وسهم حشر مضموم العدد، وكذلك أذن حشر ورفع الإثم عن المتعجل والمتأخر على وجه الإباحة وقيل : معنى رفع الإثم إنه خط ذنوبهما بإقامتهما الحج تعجل أو تأخر بشرط أن يكون متقيا- تنبيها أن الاعتبار بالتقوى فقط، وعلى ذلك دل قوله- عليه السلام- \" من حج ولم يرفث ولم يفسق رجع كيوم ولدته أمة \" ثم قال: ﴿وَٱتَّقُواْ ٱللَّهَ﴾⟪2:203⟫ متحققين أنكم إليه راجعون، وعلى أعمالكم محاسبون ...\n⟦1:427⟧"}, {"a": [204], "v": 1, "p": 427, "ev": 1, "ep": 428, "sid": 428, "t": "قوله - عز وجل -:\n﴿وَمِنَ ٱلنَّاسِ مَن يُعۡجِبُكَ قَوۡلُهُۥ فِي ٱلۡحَيَوٰةِ ٱلدُّنۡيَا وَيُشۡهِدُ ٱللَّهَ عَلَىٰ مَا فِي قَلۡبِهِۦ وَهُوَ أَلَدُّ ٱلۡخِصَامِ﴾⟪2:204⟫\nالآية (204) - سورة البقرة ..\nالتعجب حيرة تعرض للإنسان عن جهل سبب الشيء وليس هو شي ماله في ذاته حالة، بل هو بحسب الإضافات إلى من يعرف السبب وإلى من لا يعرفه، ولهذا قال قوم كل شيء عجب، وقال قوم: لا شيء عجب، وحقيقة أعجبني كذا، أي ظهر لي ظهورا لم أعرف سببه، والألد المايل اللديد، أي صفحة العنق، ثم يعبر به عن المتكبر كالمتصلف أي المشتكي صليفه والأصيد للبعير الذي به الصد، ولهذا قال الشاعر:\nويقيم سالفة العدو الأصيد\nوقال:\nإن الكريم من يلفت حوله ...\nوإن اللئيم دائم الطرف أقوده\nواستعير الألد للجدل الذي لا يمكنه صرف رأسه عما عض عليه، ولما كانت الدنيا والآخرة كالمتضادين حتى قال أمير المؤمنين: [أزنها بكفتي ميزان] لا ترجع إحداهما إلا بنقصان الأخرى، وقال: قرة كالضرتين إذا أرضيت إحداهما أسخطت الأخرى، فمن حذق في إحديهما خرق في أخرى، ولهذا قال عليه السلام في اعتباره بأهل الدنيا: \" أكثر أهل الجنة البله \"، وقال في اعتباره\n⟦1:428⟧\nبأهل الآخرة: \" ألكيس من دان نفسه .. \" نبه أن من الناس من إذا صادفته وجدته معجبا لك في أمور دنياه، وقوله تعالى: ﴿وَإِذَا رَأَيۡتَهُمۡ تُعۡجِبُكَ أَجۡسَامُهُمۡۖ﴾⟪63:4⟫ الآية ... ويحلف بأن قلبه [مطمئن بالإيمان] ومطابق للسانه وهو يجادل في ذلك ويخاصم، وقوله تعالي ﴿وَيُشۡهِدُ ٱللَّهَ عَلَىٰ مَا فِي قَلۡبِهِۦ﴾⟪2:204⟫ إشارة إلى نحو ما وصف به المنافقين، حيث قال قالوا: ﴿نَشۡهَدُ إِنَّكَ لَرَسُولُ ٱللَّهِۗ﴾⟪63:1⟫."}, {"a": [205], "v": 1, "p": 428, "ev": 1, "ep": 429, "sid": 429, "t": "قوله- عز وجل -:\n﴿وَإِذَا تَوَلَّىٰ سَعَىٰ فِي ٱلۡأَرۡضِ لِيُفۡسِدَ فِيهَا وَيُهۡلِكَ ٱلۡحَرۡثَ وَٱلنَّسۡلَۚ وَٱللَّهُ لَا يُحِبُّ ٱلۡفَسَادَ﴾⟪2:205⟫\nالآية (205) - سورة البقرة.\nالسعي: مشي سريع، ومنه قيل السعي بين الصفا والمروة، فجعل مستعارا للتصرف، ولأجله قيل لجابي الصدقة ساع، وقيل للوقيعة في الغير سعاية، وذلك كاستعارة المشي لهما في قوله ﴿هَمَّازٖ مَّشَّآءِۭ بِنَمِيمٖ﴾⟪68:11⟫ والنسل: مصدر نسل إذا خرج منفصلا ومنه: نسل الوبر والريش.\nوالنسالة للساقط منه، ونسل إذا أسرع، قال تعالى: ﴿إِلَىٰ رَبِّهِمۡ يَنسِلُونَ﴾⟪36:51⟫، وسمي الولد نسلا لكونه ناسلا عن أبويه بين تعالي حال هذا المعجب في الدنيا المرائي المجادل بأنه إذا تولى عمن يرائي سلي في الإفسال وإهلاك الحرث والنسل وذلك معاندة لله فيما حث عليه في قوله:\n⟦1:429⟧\n﴿وَٱسۡتَعۡمَرَكُمۡ فِيهَا﴾⟪11:61⟫، وما دل عليه قول النبي- عليه السلام- لما خلق الله المعيشة جعل البركة في الحرث والنسل، ولجأ أن من فعل ذلك فإن الله لا يحبه، أي لا يرضى فعله ..\nإن قيل: كيف حكم تعالى بأنه لا يحب الفساد وهو مفسد للأشياء؟\nقيل: الإفساد في الحقيقة إخراج الشيء من حالة محمودة لا لغرض صحيح، وذلك غير موجود في فعل الله تعالى، ولا هو أمر به ولا محب له، وما يراه من فعله، [ويظهر بظاهره] فسادا فهو بالإضافة إلينا ولاعتبار ما، فأما بالنظر الإلهي فكله صلاح، ولهذا قال بعض الحكماء: \" يا من إفساده إصلاح \"، أي ما نظنه إفسادا لقصور نظرنا ومعرفتنا فهو في الحقيقة إصلاح وجملة الأمر أن\nالإنسان هو زبدة هذا العالم، وما عداه مخلوق لأجله، ولهذا قال تعالى: ﴿هُوَ ٱلَّذِي خَلَقَ لَكُم مَّا فِي ٱلۡأَرۡضِ جَمِيعٗا﴾⟪2:29⟫، والمقصد من الإنسان سوقه إلى كماله الذي رشح له، فإذن إهلاك ما أمر بإهلاكه فلإصلاح الإنسان، وأما أمانته، فأحد أسباب حياته الأبدية، ولشرح هذه الجملة موضع أخر من التفسير .."}, {"a": [206], "v": 1, "p": 429, "ev": 1, "ep": 430, "sid": 430, "t": "قوله - عز وجل -:\n﴿وَإِذَا قِيلَ لَهُ ٱتَّقِ ٱللَّهَ أَخَذَتۡهُ ٱلۡعِزَّةُ بِٱلۡإِثۡمِۚ فَحَسۡبُهُۥ جَهَنَّمُۖ وَلَبِئۡسَ ٱلۡمِهَادُ﴾⟪2:206⟫\nالآية (206) - سورة البقرة.\nالمهد معروف، وتصور منه التوطئة، فقيل لكل وطيء مهد، والمهاد جعل تارة جميعا للمهد، وتارة اسمه للآلة، نحو فراش، وجعل جهنم مهادا لهم كما جعل العذاب مبشرا به في قوله: ﴿فَبَشِّرۡهُم بِعَذَابٍ أَلِيمٍ﴾ وقوله: بالإثم أي سبب الإثم وقيل: دعته العزة إلى أن يأثم، كقوله: أخدني بفعل\n⟦1:430⟧\nكذا، أي بأن أفعله وبين أن جهنم نصيبه الكافي جزاؤه الوافي، ثم دل على حال جهنم بقوله: ﴿وَلَبِئۡسَ ٱلۡمِهَادُ﴾⟪2:206⟫ ..."}, {"a": [207], "v": 1, "p": 430, "ev": 1, "ep": 432, "sid": 431, "t": "قوله - عز وجل -:\n﴿وَمِنَ ٱلنَّاسِ مَن يَشۡرِي نَفۡسَهُ ٱبۡتِغَآءَ مَرۡضَاتِ ٱللَّهِۚ وَٱللَّهُ رَءُوفُۢ بِٱلۡعِبَادِ﴾⟪2:207⟫\nالآية (207) - سورة البقرة.\nيشري يبيع ويشتري، وقد تقدم حقيقته، وحقيقة البيع والناس علي أضرب ضرب باع نفسه من الشيطان بالشهوات، فصار علقا كل يده لا سبيل إلي الانفكاك منه، وهم المعنيون بقوله: ﴿فَزَيَّنَ لَهُمُ ٱلشَّيۡطَٰنُ أَعۡمَٰلَهُمۡ فَهُوَ وَلِيُّهُمُ ٱلۡيَوۡمَ وَلَهُمۡ عَذَابٌ أَلِيمٞ﴾⟪16:63⟫، وقوله: ﴿أَفَرَءَيۡتَ مَنِ ٱتَّخَذَ إِلَٰهَهُۥ هَوَىٰهُ﴾⟪45:23⟫، وضرب وقع أسر الشريطان عليه، فاجتهد في تخليص نفسه منه وهو المعنى بقوله- عليه السلام: \" الناس عاديان، فبانع نفسه فموبقها، ومبتاع نفسه فمعتقها \"، وضرب لم يقع عليه أسر الشيطان، وقد باع نفسه من الله- عز وجل، وهو المعنى بقوله:\n﴿إِنَّ ٱللَّهَ ٱشۡتَرَىٰ مِنَ ٱلۡمُؤۡمِنِينَ أَنفُسَهُمۡ وَأَمۡوَٰلَهُم بِأَنَّ لَهُمُ ٱلۡجَنَّةَۚ﴾⟪9:111⟫، وبين تعالى كيف اشترى أنفسهم بقوله: ﴿يُقَٰتِلُونَ فِي سَبِيلِ ٱللَّهِۖ﴾، فقول: ﴿يَشۡرِي نَفۡسَهُ﴾⟪2:207⟫ يتناول ضربين: المخلص نفسه\n⟦1:431⟧\nمن أسر الشيطان، ومن باع نفسه من الله فإذن يشري نفسه للأمرين، والشراء والبيع في مثل هذا الوضع كالرمز والإشارة، وحقيقتهما وقف الإنسان نفسه على مرضاة الله - عز وجل-، والتحري في مصالح عباده، وقيل.\nإنها نزلت في صهيب بن سيار، وكان قد أخذه المشركون، وقتلوا بعض من كان مده، فقال صهيب: أنا شيخ لا أنفعكم إن كنت معكم، ولا أضركم إن كنت عليكما فخذوا مالي وخلوا سبيلي، ففعلوا فلما ورد المدينة قال له أبو بكر: ربح بذلك، فأنزل الله تعالى هذه الآية، ونبه بقوله:\n﴿وَٱللَّهُ رَءُوفُۢ بِٱلۡعِبَادِ﴾⟪2:207⟫، أن الإنسان في بيع نفسه منه تعالى يدخل في ملك من هو أرأف به من نفسه أولى به من ذاته ..\n⟦1:432⟧"}, {"a": [208], "v": 1, "p": 432, "ev": 1, "ep": 433, "sid": 433, "t": "قوله - عز وجل -:\n﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱدۡخُلُواْ فِي ٱلسِّلۡمِ كَآفَّةٗ وَلَا تَتَّبِعُواْ خُطُوَٰتِ ٱلشَّيۡطَٰنِۚ إِنَّهُۥ لَكُمۡ عَدُوّٞ مُّبِينٞ﴾⟪2:208⟫\nالآية (208) - سورة البقرة.\nعنى بالسلم سلم العبد الله - عز وجل، وذلك أن الإنسان في كفره، وكفران نعمة الله كالمحارب له، ولهذا يسمى الكافر المحارب في نحو قوله: ﴿ٱلَّذِينَ يُحَارِبُونَ ٱللَّهَ وَرَسُولَهُۥ﴾⟪5:33⟫، وسلم العباد لله على ثلاثة أضرب، ضرب يتقدمه إلى الإيمان وهو الإسلام الذي سلم به من الله أن يراق دمه ويسلب ماله وهو المغني بقوله- عليه السلام:\n\" أمرت أن أقاتل الناس حتى يقولوا لا إله إلا الله، فإذا قالوها عصموا مني دماءهم وأموالهم \".\nواثنان بعد الإيمان، أحدهما أن يسلم من سخطه بارتسام أوامره وزواجره طوعا أو كرها، والثاني: أن يكون سليما من الشيطان وأوليائه، وسليما فيما يجري من قضائه، وبه يحصل [دار السلام المذكورة في قوله تعالى]: ﴿وَٱللَّهُ يَدۡعُوٓاْ إِلَىٰ دَارِ ٱلسَّلَٰمِ﴾⟪10:25⟫ وهذا غاية ما ينتهي إليه للعبد من المنازل الثلاث وإن كان لكل منزلة منها درجات، وهذا السلم هو المغني بقوله تعالى: {}، وبقوله تعالى: ﴿إِنَّ ٱلدِّينَ عِندَ ٱللَّهِ ٱلۡإِسۡلَٰمُۗ﴾⟪3:19⟫⟦1:433⟧، وهو الذي تمناه يوسف عليه السلام- بقوله: ﴿تَوَفَّنِي مُسۡلِمٗا وَأَلۡحِقۡنِي بِٱلصَّٰلِحِينَ﴾⟪12:101⟫، وقوله: ﴿كَآفَّةٗ﴾⟪2:208⟫ حال للمخاطبين، أو للسلم وقد تقدم الكلام في قوله: ﴿وَلَا تَتَّبِعُواْ خُطُوَٰتِ ٱلشَّيۡطَٰنِۚ﴾⟪2:208⟫.\nونبه أن اتباع الشيطان خروج عن السلم، ونبه على معاداة الشيطان وأن عدواته لا تخفى، وهذا المعنى قصده الشاعر في وصف الدنيا.\nإن الليالي والأيام لو بحثت\nعن عيب نفسهما لم تكتم الخبرا."}, {"a": [209], "v": 1, "p": 433, "ev": 1, "ep": 434, "sid": 434, "t": "قوله- عز وجل -:\n﴿فَإِن زَلَلۡتُم مِّنۢ بَعۡدِ مَا جَآءَتۡكُمُ ٱلۡبَيِّنَٰتُ فَٱعۡلَمُوٓاْ أَنَّ ٱللَّهَ عَزِيزٌ حَكِيمٌ﴾⟪2:209⟫\nالآية (209) - سورة البقرة.\nزل وزال يتقاربان، ولكن زال أبلغ، ولفظ البينات عام فيما حولنا من المعارف العقلية والسمعية، والنهي عن الزلة والقصد إلى الفعل الذي يحصل عنده الزلة، إذ الإنسان لا يقصد أن يزل، وعلى هذا إذا قيل: \" لا تصلوا \"، ونبه بقوله ﴿بَعۡدِ مَا جَآءَتۡكُمُ ٱلۡبَيِّنَٰتُ﴾⟪2:209⟫ أن أعظم الذنبين ما كان بعد المعرفة والبينة، وفي هذا تحذير لمن يبصر عن ركوب ذنب فكأنه قيل: إذا أردتم ذنبا فاذكروا عز الله وحكمته، [ففي العلم بعزه علم بقدرته على عقاب المذنب]، وفي العلم بحكمته علم بأنه غير ظالم في عقابه وفي العلم بهذين انزجار سكن ارتكاب الذنب.\n⟦1:434⟧"}, {"a": [210], "v": 1, "p": 434, "ev": 1, "ep": 436, "sid": 435, "t": "قوله - عز وجل -:\n﴿هَلۡ يَنظُرُونَ إِلَّآ أَن يَأۡتِيَهُمُ ٱللَّهُ فِي ظُلَلٖ مِّنَ ٱلۡغَمَامِ وَٱلۡمَلَٰٓئِكَةُ وَقُضِيَ ٱلۡأَمۡرُۚ وَإِلَى ٱللَّهِ تُرۡجَعُ ٱلۡأُمُورُ﴾⟪2:210⟫\nالآية (210) - سورة البقرة.\nقد تصور بعض.\nالناس مالا يليق بصفات الله تعالى في لفظ المجيء والإتيان الذي وصف الله - عز وجل به بنفسه في هذه الآية وفي قوله: ﴿هَلۡ يَنظُرُونَ إِلَّآ أَن يَأۡتِيَهُمُ ٱللَّهُ﴾⟪2:210⟫ وقوله: ﴿فَأَتَىٰهُمُ ٱللَّهُ مِنۡ حَيۡثُ لَمۡ يَحۡتَسِبُواْۖ﴾⟪59:2⟫، وقوله: ﴿فَأَتَى ٱللَّهُ بُنۡيَٰنَهُم مِّنَ ٱلۡقَوَاعِدِ﴾⟪16:26⟫، وقوله: ﴿وَجَآءَ رَبُّكَ وَٱلۡمَلَكُ صَفّٗا صَفّٗا﴾⟪89:22⟫، وذلك لأمرين، أحدهما لقصورهم عن معرفة البارئ عز وجل، والثاني: لضيق مجالهم في مجاري الألفاظ ومجازها، وليس يقال الإتيان والمجئ لانتقال الحي المتحرك من مكان إلى مكان فقط، بل قد يقال لقصد القاصد بعنايته أمرا يستصلحه كقوله: أتيت المروة من بابها، [ويقال أيضا] لاستيفاء فعل يتولاه، كقولك: أتيت على ما في الكتاب، [وقد يقال أيضا] لفعل يفعله على يد من يستكفيه [كقولك إن الأمير ناحية كذا بجيش عظيم، ومنه ﴿فَلَنَأۡتِيَنَّهُم بِجُنُودٖ لَّا قِبَلَ لَهُم بِهَا﴾⟪27:37⟫ ولما جرت العادة أن الرئيس يتولى الأمير بمن يستكفيه] تارة وبنفسه تارة، وأن لا يتولى بنفسه إلا ما كان أكبر وأعظم، فلما أراد الله تعالى أن يبين العذاب الذي لا غاية وراءه جعله منسوبا إلى نفسه وإتيانا له، وعلى هذا النحو جعل كل يستعظمه فعلا له نحو خلق أدم بيده، وعلى هذا قوله: ﴿وَقَدِمۡنَآ إِلَىٰ مَا عَمِلُواْ مِنۡ عَمَلٖ فَجَعَلۡنَٰهُ هَبَآءٗ مَّنثُورًا﴾⟪25:23⟫، ووجه آخر، قد أشير إليه في صدر الكتاب، وهو أن الفعل كما ينسب إلى المباشر له ينسب إلى ما هو سببه ومسهلة، نحو أن يقال: ﴿ٱلرَّحۡمَٰنُ ۝ عَلَّمَ﴾⟪55:1-2⟫، وإنما علمنا من علمه النبي، وعلم النبي جبريل، وجبريل علمه الله عز\n⟦1:435⟧\nوجل- فصح أن ينسب إليه، ولهذا قد ينسب فعل واحد تارة إلى الله عز وجل-، وتارة إلى غيره، نحو: ﴿قُلۡ يَتَوَفَّىٰكُم مَّلَكُ ٱلۡمَوۡتِ﴾⟪32:11⟫، وقال تعالى: ﴿ٱللَّهُ يَتَوَفَّى ٱلۡأَنفُسَ حِينَ مَوۡتِهَا﴾⟪39:42⟫،،\nفإن قيل: هل يجوز على هذا القياس أن يقال شيء إذا عنى به عبدا؟\nقيل؟ نحن إنما أجزنا إستعمال ما استعمل فيه تعالى لورود السماع به، ولولا ذلك لنزهناه عن كل وصف يطلق على البشر تفاديا من وهم بشبيه، وقوله: ﴿وَقُضِيَ ٱلۡأَمۡرُۚ﴾⟪2:210⟫ تنبيها أنه حينئذ لا يمكن تلافيه، وأكد ذلك بقوله: ﴿وَإِلَى ٱللَّهِ تُرۡجَعُ ٱلۡأُمُورُ﴾⟪2:210⟫.\nأي ما قد ملكه عباده في الدنيا من الملك، والملك والتصرف مسترد منهم يوم القيامة، وراجع إليه، ويقال: رجع الأمر إلى الأمير، أي استرد ما كان فوضه إليه، وقيل: عنى بالأمور الأرواح، وسماها أمورا من حيث إنها من الإبدعات المشار إليها بقوله: ﴿إِنَّمَا قَوۡلُنَا لِشَيۡءٍ إِذَآ أَرَدۡنَٰهُ أَن نَّقُولَ لَهُۥ كُن فَيَكُونُ﴾⟪16:40⟫، وقوله: ﴿أَلَا لَهُ ٱلۡخَلۡقُ وَٱلۡأَمۡرُۗ﴾⟪7:54⟫ وقال: ولهذا لما سئل سكان الروح قال: ﴿قُلِ ٱلرُّوحُ مِنۡ أَمۡرِ رَبِّي﴾⟪17:85⟫، أي هو من الإبداع الذي لا يمكن للبشر تصوره، فنبه أن الأرواح كلها مرجوعة إليه وراجعة، كما قال تعالى: ﴿ٱللَّهُ يَتَوَفَّى ٱلۡأَنفُسَ حِينَ مَوۡتِهَا﴾⟪39:42⟫، وعلى ذلك قوله: ﴿كَمَا بَدَأَكُمۡ تَعُودُونَ﴾⟪7:29⟫، ويكون رجوعها إنما بربح وغبطة، وإما بندامة وحسرة إلى أن ينشئها النشأة الأخرى على ما قضاه تعالى، وقوله: ﴿ظُلَلٖ﴾⟪2:210⟫ جمع ظلة، يقال ظله وظلل وظلال، نحو خلة وخلل وخلال، والإشارة بهدف إما إلى أمطار عذاب، كعارض عاد المذكور في قوله: ﴿هَٰذَا عَارِضٞ مُّمۡطِرُنَاۚ﴾⟪46:24⟫، أو إلى أهوال القيامة، وقوله: ﴿هَلۡ يَنظُرُونَ﴾⟪2:210⟫ على طريق التهديد والوعيد ...\n⟦1:436⟧"}, {"a": [211], "v": 1, "p": 436, "ev": 1, "ep": 436, "sid": 437, "t": "قوله - عز وجل -:\n﴿سَلۡ بَنِيٓ إِسۡرَٰٓءِيلَ كَمۡ ءَاتَيۡنَٰهُم مِّنۡ ءَايَةِۭ بَيِّنَةٖۗ وَمَن يُبَدِّلۡ نِعۡمَةَ ٱللَّهِ مِنۢ بَعۡدِ مَا جَآءَتۡهُ فَإِنَّ ٱللَّهَ شَدِيدُ ٱلۡعِقَابِ﴾⟪2:211⟫\nالآية (211) - سورة البقرة.\nنبه بلفظ «كم» على كثرة ما آتاهم من الآيات، ودل بقوله: ﴿وَمَن يُبَدِّلۡ نِعۡمَةَ ٱللَّهِ﴾⟪2:211⟫ على إضمار بدلوا، وعلى هذا إن الحكم ليس مقصورا عليهم، بل هو عام فيهم وفي غيرهم، ودل بقوله: ﴿نِعۡمَةَ ٱللَّهِ﴾⟪2:211⟫ أن الآية من جملة نعمته، بل هي من أعظم النعم، وبقوله: ﴿مِنۢ بَعۡدِ مَا جَآءَتۡهُ﴾⟪2:211⟫ على نحو ما دل عليه قوله: ﴿مِّنۢ بَعۡدِ مَا جَآءَتۡكُمُ ٱلۡبَيِّنَٰتُ﴾⟪2:209⟫ وتقدير الكلام: آتيناهم آيات هي بنعم، فبدلوها ومن يبدل نعمت الله بعد اختصاصه بها عاقبه الله عقابا شديدا فإنه شديد العقاب، فإذن بعقاب بني إسرائيل ومن فعل فعلهم، فإنه يعاقبهم كما عاقبهم."}, {"a": [212], "v": 1, "p": 436, "ev": 1, "ep": 440, "sid": 437, "t": "قوله- عز وجل:\n﴿زُيِّنَ لِلَّذِينَ كَفَرُواْ ٱلۡحَيَوٰةُ ٱلدُّنۡيَا وَيَسۡخَرُونَ مِنَ ٱلَّذِينَ ءَامَنُواْۘ وَٱلَّذِينَ ٱتَّقَوۡاْ فَوۡقَهُمۡ يَوۡمَ ٱلۡقِيَٰمَةِۗ وَٱللَّهُ يَرۡزُقُ مَن يَشَآءُ بِغَيۡرِ حِسَابٖ﴾⟪2:212⟫\nالآية (212) - سورة البقرة.\nالتزيين التحسين المدرك بالحس دون المدرك بالعقل، ولهذا جاء في أوصاف الدنيا دون أوصاف الآخرة، نحو: ﴿زُيِّنَ لِلنَّاسِ حُبُّ ٱلشَّهَوَٰتِ﴾⟪3:14⟫، واختلف في هذا التزين، فمنهم من قال الله زينه لقوله: ﴿إِنَّ ٱلَّذِينَ لَا يُؤۡمِنُونَ بِٱلۡأٓخِرَةِ زَيَّنَّا لَهُمۡ أَعۡمَٰلَهُمۡ فَهُمۡ يَعۡمَهُونَ﴾⟪27:4⟫، ومنهم من قال: الشيطان زين لهم لقوله: ﴿وَزَيَّنَ لَهُمُ ٱلشَّيۡطَٰنُ مَا كَانُواْ يَعۡمَلُونَ﴾⟪6:43⟫، وروي عن الحسن: الشيطان زينها ولا يعلم أحد أذم لها ممن خلقها أو وصفها بأنها متاع قليل وأنها متاع الغرور وجمع بعض الملاحدة بين هذه الآية\n⟦1:437⟧\nوأخواتها وزعم أن ذلك من الآيات المتناقضة في القرآن، لأنه قال مرة: ﴿وَزَيَّنَ لَهُمُ ٱلشَّيۡطَٰنُ﴾، فقال: ﴿ٱلشَّيۡطَٰنُ سَوَّلَ لَهُمۡ﴾⟪47:25⟫، وقال في آية أخرى: ﴿زَيَّنَّا لِكُلِّ أُمَّةٍ عَمَلَهُمۡ﴾⟪6:108⟫، فنسبه إلي نفسه، وتارة ذكر أنه قيض لهم من زينها لهم، وذلك قوله: ﴿وَقَيَّضۡنَا لَهُمۡ قُرَنَآءَ فَزَيَّنُواْ لَهُم مَّا بَيۡنَ أَيۡدِيهِمۡ وَمَا خَلۡفَهُمۡ﴾⟪41:25⟫، ووهي ما ادعاه لا يخفى على ذي بصيرة، لكن بيانه يحتاج إلى مقدمة، فنقول وبالله التوفيق: إن الله- عز وجل خلق الإنسان وجعل له سبيلا إلى بقائه بشخصه زمانا ما، وتنوعه مدة ما، وركب فيه شهوة تشوقه إلى الغذاء والجماع اللذين هما سببا البقاءين، فهذا هو تزين الله عز وجل- وأمره باستعمالها حسب ما تأمره الشريعة فيها يؤدي به إلى سعادته في الآخرة على ما ينبغي، وبقدر ما ينبغي، ومن عشقها بإفراط، استحوذ الشطيان عليه وأعماه عن قبح المستقبح منه، وذلك قوله تعالى: ﴿وَزَيَّنَ لَهُمُ ٱلشَّيۡطَٰنُ أَعۡمَٰلَهُمۡ﴾ وأما قوله تعالى ﴿زَيَّنَّا لِكُلِّ أُمَّةٍ عَمَلَهُمۡ﴾⟪6:108⟫ [وقوله تعالى] ﴿زَيَّنَّا لَهُمۡ أَعۡمَٰلَهُمۡ فَهُمۡ يَعۡمَهُونَ﴾⟪27:4⟫، فالتزيين في الآيتين يحتمل وجهين أحدهما أن الذي زينه هو المشروع لهم، والثاني: أن الذي زينه هو الشهوة لكن على أن يأخذ بقدر ما يجب، وفي وقت ما يجب، لا أن يجعلها مقصده ووجه أخر في الآية، وهو: الحياة حياتان، حياة ذاتية دنيه وهي الحياة الدنيا ودناءتها لما وصفها الله تعالى بقوله ﴿ٱعۡلَمُوٓاْ أَنَّمَا ٱلۡحَيَوٰةُ ٱلدُّنۡيَا لَعِبٞ وَلَهۡوٞ وَزِينَةٞ وَتَفَاخُرُۢ بَيۡنَكُمۡ وَتَكَاثُرٞ فِي ٱلۡأَمۡوَٰلِ وَٱلۡأَوۡلَٰدِۖ كَمَثَلِ غَيۡثٍ أَعۡجَبَ ٱلۡكُفَّارَ نَبَاتُهُۥ ثُمَّ يَهِيجُ فَتَرَىٰهُ مُصۡفَرّٗا ثُمَّ يَكُونُ حُطَٰمٗاۖ﴾⟪57:20⟫\n⟦1:438⟧\nالآية ..\n، وحياة متأخر سنية وهي الموصوفة بقوله تعالى: ﴿وَإِنَّ ٱلدَّارَ ٱلۡأٓخِرَةَ لَهِيَ ٱلۡحَيَوَانُۚ﴾⟪29:64⟫ والثانية: لا يعرفها إلا الذين اتقوا، فأما الذين كفروا فلا يعرفون إلا الحياة الدنيا ويجحدون الآخرة ويسخرون من الذين يؤمنون بها، فبين الله تعالى أنهم وإن سخروا من الذين آمنوا، فالذين آمنوا فوقهم، ومعنى ﴿فَوۡقَهُمۡ﴾⟪2:212⟫ قيل هو كقوله: ﴿أَصۡحَٰبُ ٱلۡجَنَّةِ يَوۡمَئِذٍ خَيۡرٞ مُّسۡتَقَرّٗا﴾⟪25:24⟫ وذلك يحتمل وجهين، أحدهما أن حال المؤمنين في الآخرة أعلى من حال الكفار في الدنيا، والثاني: أن المؤمنين في الآخرة هم في الغرفات، وأن الكفار في الدرك الأسفل من النار وقوله: ﴿وَٱللَّهُ يَرۡزُقُ مَن يَشَآءُ بِغَيۡرِ حِسَابٖ﴾⟪2:212⟫ أي كفى ما يستحق بلا إفراط ولا تفريط، \" وأعطاه بغير حساب \" إذا أعطاه أكثر مما يستحق وأقل مما يستحق والأول هو المقصود هاهنا، وهو المشار إليه بالإحسان، وقد فسر ذلك على أوجه لاحتمال اللفظ، وإيهامه الأول يعطيه [عطاء] أكثر مما يستحقه، الثاني: يعطيه ولا يأخذ منه، الثالث: يعطيه عطاء لا يحويه حصر العباد،\nلقول الشاعر: عطاياه تحصى قبل إحصائها القطر\nالرابع: يعطيه بلا مضايقة، من قولهم: حاسبته أي ضايقته، الخامس: يعطيه أكثر مما يحسبه\nأي يكفيه، وكل هذه الوجوه تحتمل أن يكون ذلك في الدنيا وفي الآخرة، السادس: إن ذلك إشارة إلى\nتوسيعه على الكفار والفساق الذين قال فيهم: ﴿وَلَوۡلَآ أَن يَكُونَ ٱلنَّاسُ أُمَّةٗ وَٰحِدَةٗ لَّجَعَلۡنَا لِمَن يَكۡفُرُ بِٱلرَّحۡمَٰنِ لِبُيُوتِهِمۡ سُقُفٗا مِّن فِضَّةٖ﴾⟪43:33⟫ تنبيها أن لا فضيلة في المال، ولا إكرام لمن يوسع عليه ما لم\n⟦1:439⟧\nيستعن به في الوصول إلى المطلوب منه، ولهذا قال: ﴿أَيَحۡسَبُونَ أَنَّمَا نُمِدُّهُم بِهِۦ مِن مَّالٖ وَبَنِينَ ۝ نُسَارِعُ لَهُمۡ فِي ٱلۡخَيۡرَٰتِۚ﴾⟪23:55-56⟫ الآية ...\nولهذا قال أمير المؤمنين: \" من وسع عليه في دنياه فلم يعلم أنه مكر به فقد خدع عن عقله \".\nالسابع: يعطي أولياءه بلا تبعه ولا حساب عليهم فيما يعطون، وذاك أن المؤمن لا يأخذ من عرض الدنيا إلا من حيث يجب، وفي وقت ما يجب وعلى الوجه الذي يجب، ولا ينفقه إلا على ذلك، فهو يحاسب نفسه فلا يحاسب، ولهذا ما روي: \" من حاسب نفسه في الدنيا أمن الحساب في القيامة \"، وعلى هذا قال لسليمان: ﴿هَٰذَا عَطَآؤُنَا فَٱمۡنُنۡ أَوۡ أَمۡسِكۡ بِغَيۡرِ حِسَابٖ﴾⟪38:39⟫ أي: تحر فيما أعطيناك الوجه الذي لا تبعة فيه عليك ولا حساب، الثامن: أن الله عز وجل- يقابل المؤمني في القيامة لا بقدر استحقاقهم، بل بأكثر منه كما قال: ﴿مَّن ذَا ٱلَّذِي يُقۡرِضُ ٱللَّهَ قَرۡضًا حَسَنٗا فَيُضَٰعِفَهُۥ لَهُۥٓ﴾.\nالتاسع: وهو يقارب ذلك إن ذلك إشارة إلى ما روي أن أهل الجنة لا خطر عليهم، وعلى ذلك قوله تعالى: ﴿وَفِيهَا مَا تَشۡتَهِيهِ ٱلۡأَنفُسُ وَتَلَذُّ ٱلۡأَعۡيُنُۖ﴾⟪43:71⟫، وقوله: ﴿فَأُوْلَٰٓئِكَ يَدۡخُلُونَ ٱلۡجَنَّةَ يُرۡزَقُونَ فِيهَا بِغَيۡرِ حِسَابٖ﴾⟪40:40⟫، وأما تعلقه بما تقدم، فعلى بعض هذه التفاسير يتعلق بالذين كفروا، وعلى بعضه يتعلق بالذين آمنوا ..\n⟦1:440⟧"}, {"a": [213], "v": 1, "p": 440, "ev": 1, "ep": 442, "sid": 441, "t": "قوله - عز وجل -:\n﴿كَانَ ٱلنَّاسُ أُمَّةٗ وَٰحِدَةٗ فَبَعَثَ ٱللَّهُ ٱلنَّبِيِّـۧنَ مُبَشِّرِينَ وَمُنذِرِينَ وَأَنزَلَ مَعَهُمُ ٱلۡكِتَٰبَ بِٱلۡحَقِّ لِيَحۡكُمَ بَيۡنَ ٱلنَّاسِ فِيمَا ٱخۡتَلَفُواْ فِيهِۚ وَمَا ٱخۡتَلَفَ فِيهِ إِلَّا ٱلَّذِينَ أُوتُوهُ مِنۢ بَعۡدِ مَا جَآءَتۡهُمُ ٱلۡبَيِّنَٰتُ بَغۡيَۢا بَيۡنَهُمۡۖ فَهَدَى ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ لِمَا ٱخۡتَلَفُواْ فِيهِ مِنَ ٱلۡحَقِّ بِإِذۡنِهِۦۗ وَٱللَّهُ يَهۡدِي مَن يَشَآءُ إِلَىٰ صِرَٰطٖ مُّسۡتَقِيمٍ﴾⟪2:213⟫\nالآية (213) - سورة البقرة.\nقال ابن عباس وأبي والسدى: \" كانوا أمة واحدة في الإيمان \" وقال غيرهم: \" في الكفر \"، وهدا الخلاف لاختلاف نظرين لابد فيهما من مقدمة تنكشف بها أوجه الخلاف، وتحقيق التأويل، وهي أن الله - عز وجل - فطر الناس فطرة ركز فيها رؤية يعرف بها بعض الأشياء اضطرارا، ومكنه أن يعرف بها البعض اكتسابا، وحبب إليه ما لم يفسد الحق من الاعتقاد دون الباطل والجميل من الفعال دون القبيح والصدق من المقال دون الكذب وإلى ذلك أشار بقوله - عز وجل:\n﴿فِطۡرَتَ ٱللَّهِ ٱلَّتِي فَطَرَ ٱلنَّاسَ عَلَيۡهَاۚ﴾⟪30:30⟫، وبقوله: ﴿صِبۡغَةَ ٱللَّهِ﴾⟪2:138⟫ وبقوله: ﴿وَإِذۡ أَخَذَ رَبُّكَ مِنۢ بَنِيٓ ءَادَمَ مِن ظُهُورِهِمۡ ذُرِّيَّتَهُمۡ﴾⟪7:172⟫ الآية، وبقول النبي - عليه السلام -: \" كل مولود يولد على الفطرة \"، ولم يخلهم في وقت من نبي يشحذ عقولهم ويعرفهم ما لا سبيل لهم إلى معرفته من دونه، وكان كلما\n⟦1:441⟧\nتختل أحوالهم بعد خروج نبيهم من بينهم، إما أن يقيض لهم من يجدد عليهم شريعتهم السالفة، أو يبعث إليهم نبيا يأتيهم بشريعة مستأنفة، وهذا كان فعله إلى أن ينتهي الأمر إلى نبينا - عليه السلام -، فختم به الأنبياء، فمن قالوا: كانوا أمة في الإيمان، فنظر منه إلى المبدأ وحال الفطرة وما كانوا عليه قبل أن فسدوا، ومن قالوا: كانوا أمة واحدة في الكفر، فنظر منه إلى حين فسادهم، كما بين زمن بعثة نوح وبعثة إبراهيم - عليهما السلام، وكل واحد من القولين صحيح بنظر ونظر، فقد كانوا أمة واحدة في الإيمان طورا، وأمة واحدة في الكفر طورا ..\nإن قيل: كيف كانوا أمة واحدة في الكفر وقد قيل: لا تخلو الأرض من حجة الله؟.\nقيل إن من كان حجة الله - عز وجل - في مثل ذلك الوقت في حكم من لا اعتداد به في كونهم أمة لعلة الإصغاء إليه، وبين تعالى أنه بعث أنبياءه مبشرين للمحسنين ومنذرين للمسيئين، ولم يخل أحدا من أنبيائه من كتاب يرشده ويرشدهم،\nإن قيل:\nأليس قد قلتم: لم ينزل الكتاب من النبيين إلا على جماعة منهم؟ قيل: إن الله - عز وجل - لم يخل أحدا من الأنبياء من كتاب، إما كتاب خص هو به، وإما كتاب من كان فبله أمر بالاعتماد عليه، كالأسباط الذين كانوا أنبياء، وكتابهم كان التوراة، وعطف قوله ﴿فَهَدَى ٱللَّهُ ٱلَّذِينَ ءَامَنُواْ﴾⟪2:213⟫ على قوله: ﴿وَأَنزَلَ مَعَهُمُ﴾⟪2:213⟫، وفصل بينهما بذكر اختلافهم، وأنهم لم يختلفوا إلا من بعد ما جاءتهم البينات ذما للمختلفين، فإن من شأن البينات أن ترفع الخلاف، وعلى هذا قوله: ﴿وَلَقَدۡ بَوَّأۡنَا بَنِيٓ إِسۡرَٰٓءِيلَ مُبَوَّأَ صِدۡقٖ وَرَزَقۡنَٰهُم مِّنَ ٱلطَّيِّبَٰتِ فَمَا ٱخۡتَلَفُواْ حَتَّىٰ جَآءَهُمُ ٱلۡعِلۡمُۚ﴾⟪10:93⟫ الآمة ..\nوبين سبب اختلافهم بقوله الله عز وجل - بغيا بينهم تنبيها أن ذلك كان لطلبهم زخرف الدنيا ومنازلها، فمن المفسرين من جعل قوله: ﴿ٱلَّذِينَ أُوتُواْ ٱلۡكِتَٰبَ﴾ مخصوصا في بني إسرائيل والذين آمنوا في هذه الأمة، لقوله: ﴿وَلَا تَكُونُواْ كَٱلَّذِينَ تَفَرَّقُواْ وَٱخۡتَلَفُواْ مِنۢ بَعۡدِ مَا جَآءَهُمُ ٱلۡبَيِّنَٰتُۚ﴾⟪3:105⟫⟦1:442⟧، وقول النبي - عليه السلام: \" هدانا الله لما اختلفوا فيه \"، ومنهم من جعله عاما في جميع الأمم، وقوله بالحق، أي بما يسمى من الثواب والعقاب، وقيل بالأمر والنهي وكلاهما مرادان، فالكتاب مشتمل على كل ذلك، وقوله: (بإذنه) أي بعلمه، وقيل: بأمره، وقيل: بلطفه، والأذن لما يسمع، ويعبر به عن العلم إذ هو مبدأ العلم فينا ...\nإن قيل: كيف قال: ﴿وَٱللَّهُ يَهۡدِي مَن يَشَآءُ﴾⟪2:213⟫، وذلك يقتضي أنه هدى بعضا دون بعض، وحق جوده وكرمه أن يعمهم بالهدى؟ قيل: إنه قد عمهم من حيت قد أباحه لهم وقيضه، لكن لم يهتد به الكل، فإن هدايته لا يدركها إلا من جلى بصيرته، وشحذ فهمه ليعرفه، فيهتدي به، وقد قال بعض الصالحين: ما أكثر الهدى وأقل من يرى، ألا ترى أن نجوم المساء ما أكثرها، ولا يهتدي بها إلا العلماء؟"}, {"a": [214], "v": 1, "p": 442, "ev": 1, "ep": 444, "sid": 443, "t": "قوله - عز وجل -:\n﴿أَمۡ حَسِبۡتُمۡ أَن تَدۡخُلُواْ ٱلۡجَنَّةَ وَلَمَّا يَأۡتِكُم مَّثَلُ ٱلَّذِينَ خَلَوۡاْ مِن قَبۡلِكُمۖ مَّسَّتۡهُمُ ٱلۡبَأۡسَآءُ وَٱلضَّرَّآءُ وَزُلۡزِلُواْ حَتَّىٰ يَقُولَ ٱلرَّسُولُ وَٱلَّذِينَ ءَامَنُواْ مَعَهُۥ مَتَىٰ نَصۡرُ ٱللَّهِۗ أَلَآ إِنَّ نَصۡرَ ٱللَّهِ قَرِيبٞ﴾⟪2:214⟫\nالآية (214) - سورة البقرة.\nالزلزلة: شدة الحركة، وأصلها زل، ولزيادة المعنى زيد لفظه، وعلى هذا دل ودلدل، وما أشبهه به من المضعف مع الحرف المكرر بين تعالى أنه لا سبيل للناس كافة إلي الجنة إلا بتحمل المشاق، ولهذا\n⟦1:443⟧\nولهذا قال عليه السلام:\n\" حفت الجنة بالمكاره، وحفت النار بالشهوات \"، فخاطب هذه الأمة بأنه محال أن ترجو تحصيل الجنة إلا بما جرى به حكم الله في الذين سلفوا، وهو أن تنالكم البأساء أي الفقر، والضراء أي المصائب، والزلزلة أي المخاوف، وبذلك أثنى على المؤمنين فقال: ﴿وَٱلصَّٰبِرِينَ فِي ٱلۡبَأۡسَآءِ وَٱلضَّرَّآءِ وَحِينَ ٱلۡبَأۡسِۗ أُوْلَٰٓئِكَ ٱلَّذِينَ صَدَقُواْۖ وَأُوْلَٰٓئِكَ هُمُ ٱلۡمُتَّقُونَ﴾⟪2:177⟫ وليس ذلك في الأمور الإلهية فقط، بل في عامة الملاذ لا سبيل إلى منحة إلا بمنحة، ولا إلى لذة إلا بشدة.\nولهذا قيل: ولابد دون الشهد من أثر النحل.\nوقوله: ﴿وَزُلۡزِلُواْ حَتَّىٰ يَقُولَ ٱلرَّسُولُ﴾⟪2:214⟫، قيل معناه: \" حتى يقول الرسول والمؤمنون متى نصر الله \" على سبيل الإبطاء، ثم تل تداركوا، وعادوا إلى معرفتهم، فقالوا: ﴿أَلَآ إِنَّ نَصۡرَ ٱللَّهِ قَرِيبٞ﴾⟪2:214⟫ [قيل ليس ذلك على سبيل التضجر، بل على سبيل الدعاء والتضرع إخبارا منه تعالى على سبيل الآية لهم على سبيل الحكم، وقيل تقديره وزلزلوا حتى يقول الأتباع متى نصر الله، ويقول الرسول \" ألا إن نصر الله قريب \"] فجمع بين قولهم، كقولك: قال زيد وعمر وكذا وكذا الشيئين أحدهما قاله زيد والآخر قاله عمرو، وقرئ: ﴿حَتَّىٰ يَقُولَ﴾⟪2:214⟫ بالرفع والنصب، ولكل واحد وجهان فأحد وجهي النصب معناه: إلى أن، والثاني معناه: كي يقول، وأحد وجهي الرفع أن يكون الفعلين ماضيين نحو: \" مشيت حتى أدخل البصرة \"، أي مشيت فدخلت والثاني: أن يكون ما بعد حتى لم يمض نحو: \" مرض حتى لا يرجونه \".\n⟦1:444⟧"}, {"a": [215], "v": 1, "p": 444, "ev": 1, "ep": 445, "sid": 445, "t": "قوله - عز وجل:\n﴿يَسۡـَٔلُونَكَ مَاذَا يُنفِقُونَۖ قُلۡ مَآ أَنفَقۡتُم مِّنۡ خَيۡرٖ فَلِلۡوَٰلِدَيۡنِ وَٱلۡأَقۡرَبِينَ وَٱلۡيَتَٰمَىٰ وَٱلۡمَسَٰكِينِ وَٱبۡنِ ٱلسَّبِيلِۗ وَمَا تَفۡعَلُواْ مِنۡ خَيۡرٖ فَإِنَّ ٱللَّهَ بِهِۦ عَلِيمٞ﴾⟪2:215⟫ الآية (215) - سورة البقرة\nلما أثنى الله في غير موضع على المنفقين وحث على الإنفاق، نحو قوله: ﴿وَمِمَّا رَزَقۡنَٰهُمۡ يُنفِقُونَ﴾، وقوله: ﴿وَأَنفِقُواْ مِن مَّا رَزَقۡنَٰكُم﴾⟪63:10⟫ سألوا عنه ههنا -،\nإن قيل: ليس جوابهم طبقة لسؤالهم فإن سؤالهم عما ينفق، والجواب عمن ينفق عليه قيل: في ذلك جوابان، أحدهما أنهم سألوا عنهما وقالوا: ما ينفق؟ وعلى من ينفق؟ ولكن حذف في حكاية السؤال أحدهما إيجازا، ودل عليه الجواب بقوله: ﴿مَآ أَنفَقۡتُم مِّنۡ خَيۡرٖ﴾⟪2:215⟫، كأنه قيل: المنفق هو الخير، والمنفق عليهم هؤلاء، فلفف أحد الجوابين في الآخر، وهذا طريق معروف في البلاغة، والجواب الثاني أن السؤال ضربان سؤال جدل وحقه أن يطابقه جوابه لا زائدا عليه ولا ناقصا عنه، وسؤال تعلم، وحق المعلم أن يصير فيه كطبيب دقيق يتحرى شفاء سقيم، فيطلب ما يشفيه طلبه المريض، أو لم يطلبه فلما كان حاجتهم إلي من ينفق عليهم كحاجتهم إلى ما ينفق بين لهم الأمرين،\nإن قيل: كيف خص هؤلاء النفر دون غيرهم؟\nقيل: إنما ذكر من ذكر على سبيل المثال لمن ينفق عليهم لا على سبيل الحصر والاستيعاب، إذ أصناف المنفق عليهم على ما قد ذكرهم في غير هذا الموضع، ولما كان المندوب إلى الإنفاق عليهم صنفين صنف لهم فرض معين في مال الأغنياء، وصنف لا فرض لهم معينا ذكر الأبوين والأقارب تنبيها أن حقهم واجب، وقوله: ﴿مِّنۡ خَيۡرٖ﴾⟪2:215⟫ أي من مال، فسمي المال خيرا تنبيها أن الذي يجوز إنفاقه هو الحلال الذي يتناوله اسم الخير، كما قال: ﴿إِن تَرَكَ خَيۡرًا﴾⟪2:180⟫ ثم بين تعالي أن كل ما يفعلونه لا يخفى عليه على الوجه الذي يفعلونه، [تنبيها أنه يجازى به] نحو قوله: ﴿فَمَن يَعۡمَلۡ مِثۡقَالَ ذَرَّةٍ خَيۡرٗا يَرَهُۥ ۝ وَمَن يَعۡمَلۡ مِثۡقَالَ ذَرَّةٖ شَرّٗا يَرَهُۥ﴾⟪99:7-8⟫\n⟦1:445⟧"}, {"a": [216], "v": 1, "p": 445, "ev": 1, "ep": 446, "sid": 446, "t": "قوله - عز وجل:\n﴿كُتِبَ عَلَيۡكُمُ ٱلۡقِتَالُ وَهُوَ كُرۡهٞ لَّكُمۡۖ وَعَسَىٰٓ أَن تَكۡرَهُواْ شَيۡـٔٗا وَهُوَ خَيۡرٞ لَّكُمۡۖ وَعَسَىٰٓ أَن تُحِبُّواْ شَيۡـٔٗا وَهُوَ شَرّٞ لَّكُمۡۚ وَٱللَّهُ يَعۡلَمُ وَأَنتُمۡ لَا تَعۡلَمُونَ﴾⟪2:216⟫ الآبة (216) - سورة البقرة\nالكره في الإنسان يستعمل على ضربين، أحدهما ما يعاف من حيث الطبع، والثاني ما يعاف من حيث الفعل وإن مال إليه الطبع، ولهذا يصح أن يوصف الشيء بأنه مراد مكروه، والكره والكره قيل هما واحد في معنى نحو الضعف والضعف وقيل بل الكره المشقة التي يحمل عليها الإنسان بإكراه، والكره ما يتحمله بلا إكراه، من غيره، وقيل للحرب كريهة ...\nوعسى طمع وإشفاق، وقد يجري مجرى لعل، ويقال: هو عس بكذا، أي جدير، وأعس به، وسمي الإبل التي لا ألبان بها، وفيها طمع المعسيات من حيث أن يقال عسى أن يكون بها لبن والقتال المكتوب من حيث الظاهر مجاهدة الكفار، وقيل: عني مع ذلك مجاهدة النفس إلى الشهوة، وهي التي سماها النبي - صلى الله عليه وسلم - الله \" الجهاد الأكبر \"، ونبه بقوله: ﴿وَعَسَىٰٓ أَن تَكۡرَهُواْ﴾⟪2:216⟫ بألطف وجه على أن ما كتب عليهم من القتال خير لهم بأوضح الأدلة وهي أنه إذا جاز أن يكون منكم كراهية لأمر وفيه الخير، فيجوز أن يكون كراهتكم لما كتب عليكم من القتال كذلك، وإذا جاز أن تحبوا شيئا وهو شر لكم، فيجوز أن تكون محبتكم لما أحببتموه شرا، ثم نبه أن هذا الجائز كونه عندكم هو واجب كونه في نفسه بقوله: ﴿وَٱللَّهُ يَعۡلَمُ وَأَنتُمۡ لَا تَعۡلَمُونَ﴾⟪2:216⟫ أي إذا كان الله - عز وجل - يعلم وأنتم لا تعلمون، وقد قضي بأن ذلك خيرا، فإنما قضي به لأنه خير، وإذا كان خيرا فيحبب أن تحبوه، ولا تكرهوه، فالخير يجب إرادته، والشر يجب كراهته، وعلى نحوه دل قوله تعالى: ﴿فَعَسَىٰٓ أَن تَكۡرَهُواْ شَيۡـٔٗا وَيَجۡعَلَ ٱللَّهُ فِيهِ خَيۡرٗا كَثِيرٗا﴾⟪4:19⟫\n⟦1:446⟧\nوإياه قصد الشاعر:\nقضى الله في بعض المكاره للفتى ...\nبرشد وقي يعض الهوى مأ يحاذر .."}, {"a": [217], "v": 1, "p": 446, "ev": 1, "ep": 448, "sid": 447, "t": "قوله - عز وجل -:\n﴿يَسۡـَٔلُونَكَ عَنِ ٱلشَّهۡرِ ٱلۡحَرَامِ قِتَالٖ فِيهِۖ قُلۡ قِتَالٞ فِيهِ كَبِيرٞۚ وَصَدٌّ عَن سَبِيلِ ٱللَّهِ وَكُفۡرُۢ بِهِۦ وَٱلۡمَسۡجِدِ ٱلۡحَرَامِ وَإِخۡرَاجُ أَهۡلِهِۦ مِنۡهُ أَكۡبَرُ عِندَ ٱللَّهِۚ وَٱلۡفِتۡنَةُ أَكۡبَرُ مِنَ ٱلۡقَتۡلِۗ وَلَا يَزَالُونَ يُقَٰتِلُونَكُمۡ حَتَّىٰ يَرُدُّوكُمۡ عَن دِينِكُمۡ إِنِ ٱسۡتَطَٰعُواْۚ وَمَن يَرۡتَدِدۡ مِنكُمۡ عَن دِينِهِۦ فَيَمُتۡ وَهُوَ كَافِرٞ فَأُوْلَٰٓئِكَ حَبِطَتۡ أَعۡمَٰلُهُمۡ فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۖ وَأُوْلَٰٓئِكَ أَصۡحَٰبُ ٱلنَّارِۖ هُمۡ فِيهَا خَٰلِدُونَ﴾⟪2:217⟫\nالآية (217) - سورة البقرة.\nالصد ناحية الشعب، والوادي المانع للسالك وصده عن كذا، كأنما جعل بينه وبين ما يريده صدأ يمنعه، والصديد ما حال بين الجلد واللحم من القيح والدم، وقد تقدم أن زل وزال يتقارب لما كان الزوال معناه للنفي ضم إليه (ما) النافية، فصارا معا للإثبات، ولهذا لا يصح أن يقال: (مازال زيد إلا خارجأ)، كما يقال: (ما كان إلا خارجا)، والحبط فساد يلحق الماشية في بطونها من أكل الكلأ، واستعير لفساد العمل، والسائل على ذلك قيل أهل الشرك قصدا إلى تعبير المسلمين مما استجازوه من القتل في الشهر الحرام وقيل: هم أهل الإسلام.\nإن قيل: ما فائدة ذكر الشهر ثم إبدال القتال منه ولم يقل: يسألونك عن قتال في الشهر؟ قيل: في ذكر الشهر أولا، ثم إبدال القتال منه ولم يقل: (يسألونك عن قتال في الشهر) قيل: في ذكر الشهر أولا بنية أن السؤال عن القتال لأجل الشهر لا لغيره، ولو قيل: (يسألونك عن قتال الشهر) لكان يصح أن يفيد أن الغرض في السؤال عن القتال لا لتعظيم الشهر، بل لشيء آخر، وعلى هذا إذا قيل: \" سرق\n⟦1:447⟧\nزيد ثوبه \" تنبيها أن المقصد أن يذكر حال زيد، لا أن يخبر بسرقة ثوب ما ...\nإن قيل: لم لم يقل: القتال فيه كبير، وشروط النكرة المذكورة إدا أعيد ذكرها أن يعاد معرفا نحو سألتني عن رجل، والرجل كذا وكذا؟ قيل: في ذكره منكرا تنبيه أن ليس كل القتال في الشهر الحرام هذا حكمه، فإن قتال النبي- عليه السلام- لأهل مكة لم يكن هذا حكمه، وقد قال: \" أحلت لي ساعة من نهار).\nوقوله: ﴿وَٱلۡمَسۡجِدِ ٱلۡحَرَامِ﴾⟪2:217⟫ معطوف على قوله: ﴿عَنِ ٱلشَّهۡرِ ٱلۡحَرَامِ﴾⟪2:217⟫ فأعلم تعالى أن بعض القتال فيه كبير ﴿وَصَدٌّ عَن سَبِيلِ ٱللَّهِ﴾⟪2:217⟫ تنبيه أنه على الوجه الذي يفعله الكفار صد عن سبيل الله، أي عن دينه وعن نبيه، وأكثر منه عند الله وأعظم إخراج أهل المسجد [يعني].\nوالمؤمنين الذين هم أولياؤه، وعلى ذلك دل بقوله لهم: ﴿وَمَا لَهُمۡ أَلَّا يُعَذِّبَهُمُ ٱللَّهُ وَهُمۡ يَصُدُّونَ عَنِ ٱلۡمَسۡجِدِ ٱلۡحَرَامِ وَمَا كَانُوٓاْ أَوۡلِيَآءَهُۥٓۚ إِنۡ أَوۡلِيَآؤُهُۥٓ﴾⟪8:34⟫، ثم بين أن النبي- عليه السلام- وأمته هم أولياؤه بقوله: ﴿إِنۡ أَوۡلِيَآؤُهُۥٓ إِلَّا ٱلۡمُتَّقُونَ﴾⟪8:34⟫، وفي ذلك تنبيه أن قتال المسلمين وقتلهم فيه ليس بكبير ولا صد سكن سبيل الله عز وجل، وبين أن الفتنة أكبر من القتل، وقد تقدم الكلام فيه، وأنه لا يرضيهم إلا ارتداء كم، ﴿وَلَا يَزَالُونَ يُقَٰتِلُونَكُمۡ حَتَّىٰ يَرُدُّوكُمۡ عَن دِينِكُمۡ إِنِ ٱسۡتَطَٰعُواْۚ﴾⟪2:217⟫، ونبه بقوله: ﴿إِنِ ٱسۡتَطَٰعُواْۚ﴾⟪2:217⟫ أنهم لا يردونكم، لأنهم لا يستطيعون، وذلك نحو قوله: ﴿وَلَن تَرۡضَىٰ عَنكَ ٱلۡيَهُودُ وَلَا ٱلنَّصَٰرَىٰ حَتَّىٰ تَتَّبِعَ مِلَّتَهُمۡۗ﴾⟪2:120⟫ وعقب دلك بوعيد من يرتد، فمات على حالته، وإن أعماله المتقدمة المعمولة في سبب الدنيا والآخرة تبطل وتضمحل كما قال:\n﴿وَقَدِمۡنَآ إِلَىٰ مَا عَمِلُواْ مِنۡ عَمَلٖ فَجَعَلۡنَٰهُ هَبَآءٗ مَّنثُورًا﴾⟪25:23⟫.\n⟦1:448⟧"}, {"a": [218], "v": 1, "p": 448, "ev": 1, "ep": 449, "sid": 449, "t": "قوله - عز وجل -:\n﴿إِنَّ ٱلَّذِينَ ءَامَنُواْ وَٱلَّذِينَ هَاجَرُواْ وَجَٰهَدُواْ فِي سَبِيلِ ٱللَّهِ أُوْلَٰٓئِكَ يَرۡجُونَ رَحۡمَتَ ٱللَّهِۚ وَٱللَّهُ غَفُورٞ رَّحِيمٞ﴾⟪2:218⟫\nالآية (218) - سورة البقرة.\nالهجر.\nمفارقة الإنسان غيره، إما بالبدن أو بالنسيان والقلب، والهاجرة الساعة التي تمنع عن السير كأنها هجرت الناس بحرها، والهجار حبل يشد به الفحل، فيصير سببا لهجرانه الإبل، وجعل بناؤه على بناء الآلات، كالعقال والزمام، والهجر: الكلام المهجور لقبحه، وقيل: هجر فلان إذا هدى عن قصد واهجر المريض إذا هذي عن غير قصد والجهد: تحمل المشقة ومجاهدة العدو ومقاومته ببذل الجهد، وجهدت رأيي واجتهدته أتعبته بالفكر والنظر، والرجاء الوقوف على رجاء الأمل، أي ناحيتها حيث ما يتردد بين الأمل واليأس لما بين الله تعالي وجوب المقابلة ونهى عن تضييع الشهر الحرام والمسجد الحرام.\nوعن تهييج الفتنة نبه على فضل من هاجر وجاهد في سبيل الله محافظة على ذلك، فمن المفسرين من حمل المهاجرة على مهاجرة الأهل والولد، كهجرة النبي- عليه السلام- وأصحابه والمجاهدة على الغزو، ومنهم من قال: عنى ذلك هجران الشهوات، ومجاهدة الهوى كما روى: (جاهدوا أهواءكم كما تجاهدون أعداءكم) وقوله: (رجعتم من الجهاد الأصغر إلي الجهاد الأكبر)، وقال في حجة الوداع: (المجاهد من جاهد نفسه في طاعة الله، المهاجر من هجر الخطايا) وهذه المنازل الثلاث التي هي الإيمان والمهاجرة والجهاد هي المعنية بقوله: ﴿يَٰٓأَيُّهَا ٱلَّذِينَ ءَامَنُواْ ٱتَّقُواْ ٱللَّهَ وَٱبۡتَغُوٓاْ إِلَيۡهِ ٱلۡوَسِيلَةَ وَجَٰهِدُواْ فِي سَبِيلِهِۦ﴾⟪5:35⟫⟦1:449⟧ ولا سبيل إلي المهاجرة إلا بعد الإيمان، ولا إلى الجهاد في سبيله إلا بعد هجران الشهوات، ومن وصل إلي ذلك فحق له أن يرجو رحمته،\nإن قيل: الإنسان راج لرحمة الله وإن لم يبلغ هذه المنازل، قيل: إن الذي نسميه رجاء لن لم يبلغ مثل هذه المنازل، فهو تمن على الله المعني بقوله عليه السلام: \" والعاجز من أتبع نفسه هواها وتمنى علي الله الأماني \" أو رجاء لتفصيل غير مستحق، وما ذكره الله- عز وجل- هاهنا هو الرجاء المستحق الذي وصف به المؤمنين في غير موضع نحو قوله: ﴿وَيَرۡجُونَ رَحۡمَتَهُۥ وَيَخَافُونَ عَذَابَهُۥٓۚ﴾⟪17:57⟫ ...\nإن قيل: لم ذكر المؤمنين برجاء الرحمة وهي لهم لا محالة؟ قيل: المؤمن وإن بذل الجهد في طاعته، فواجب أن يكون بين نظرين، نظر إلى سعة رحمة الله عز وجل، ونظر إلى ما عسى أن يقع أو وقع منه من ذنب فينتج له خوفا ..."}, {"a": [219], "v": 1, "p": 449, "ev": 1, "ep": 453, "sid": 450, "t": "قوله- عز وجل -:\n﴿يَسۡـَٔلُونَكَ عَنِ ٱلۡخَمۡرِ وَٱلۡمَيۡسِرِۖ قُلۡ فِيهِمَآ إِثۡمٞ كَبِيرٞ وَمَنَٰفِعُ لِلنَّاسِ وَإِثۡمُهُمَآ أَكۡبَرُ مِن نَّفۡعِهِمَاۗ وَيَسۡـَٔلُونَكَ مَاذَا يُنفِقُونَۖ قُلِ ٱلۡعَفۡوَۗ كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلۡأٓيَٰتِ لَعَلَّكُمۡ تَتَفَكَّرُونَ﴾⟪2:219⟫\nالآية (219) - سورة البقرة.\nالخمر: ستر الشيء وقال لما يستتر به خمار، لكن للخمار صار الخمار في التعارف لما تغطي به المرأة رأسها، واختمرت المرأة، وتخمرت، وخمرت الإناء غطيته، وكذلك خمرت العجين، وسميت الخميرة لكونها مخمورة، ودخل في خمار الناس أي في جماعتهم يسترونه، والخمار الموروث من الخمر جعل ماؤه ماء الأدواء، نحو الكباد، والصداع، وخامره الحزن إذا استولى عليه حتى سترفهمه وفكره، وبنحوه سوي غما، وأصله من الستر، ومن الناس من جعل الخمر اسما لدى مسكر، ومنهم من جعله\n⟦1:450⟧\nاسما للمتحد من التمر والعنب، لقوله- عليه السلام-: \" الخمر من هاتين الشجرتين النخلة والعنبة \"، ومنهم من جعلها اسما لما لم يكن مطبوخا، ثم كمية الطبخ الذي يخرجها عن كونه خمرا مختلف فيها، والميسر آلة اليسر، أي الضرب بالقداح ويقال للضارب به ياسر، وسمي الجاذر، وذلك الجذور ياسرا تشبيها به، وأصله من اليسر، وهو ضد العسر، وسمي الغنى يسرا، وسمي ذلك يسرا لاعتقادهم أنه غني للفقراء وأشار الله- عز وجل- بقوله: ﴿وَإِثۡمُهُمَآ أَكۡبَرُ مِن نَّفۡعِهِمَاۗ﴾⟪2:219⟫ إلى تحريمه إشارة لطيفة تحتاج في كشفها إلى مقدمة، وهي أن النفع ضربان، ديني ودنيوي، والدنيوي ضربان، نفع ضروري، ونفع غير ضروري، فالضروري كالأكل والجماع اللذين لو تصورناهما مرتفعين لارتفع بارتفاع الجماع نوع الحيوان، وبارتفاع اجل أشخاص الحيوان، ونفع غير ضروري، كالتنقل بعد الأكل وترك التحلل بعده، والخمر نفعها دنيوي غير ضروري، فإن نفعها تقوية الأبدان المسنة، وهضم طعام والمعاونة على الباءة والزيادة في الرطوبة والحرارة الغريزيتين، وليس ذلك بضروري ولا متحقق النفع فيه، وفيهما إثم\nمتحقق أو مظنون، والعقل يقتضي أن يتحاشى من الترام الإثم المظنون للنفع المتحقق الذي ليس بضروري، فكيف من النفع المظنون؟، ومن هذا الوجه صار الخمر فيما بين الأمم المتقدمة مترددة بين خمر، ودم، وإباحة، وحظر، وتركها عامة في العقول الراجحة لما أراد الله تبارك وتعالى تحريم الخمر على الناس لما رأى في ذلك من المصلحة، وعلم من غريزتهم التي غرزها عليها إن كثيرا منهم إذا ردع عما ألفه واستحسنه لا يكاد يرتدع ابتداء بتقبيح السكر في نفوسهم، ولكونه منافيا لذكر الله وعبادته،\n⟦1:451⟧\nفقال: ﴿لَا تَقۡرَبُواْ ٱلصَّلَوٰةَ وَأَنتُمۡ سُكَٰرَىٰ حَتَّىٰ تَعۡلَمُواْ مَا تَقُولُونَ﴾⟪4:43⟫ فلما رسخ ذلك في نفوسهم أنزل قوله: ﴿قُلۡ فِيهِمَآ إِثۡمٞ كَبِيرٞ وَمَنَٰفِعُ لِلنَّاسِ وَإِثۡمُهُمَآ أَكۡبَرُ مِن نَّفۡعِهِمَاۗ﴾⟪2:219⟫، وكأن في هذا إشارة لا يعرفها إلا ذوو العقول الراجحة، فلما قوي ذلك في نفوسهم فال تعالى: ﴿إِنَّمَا ٱلۡخَمۡرُ وَٱلۡمَيۡسِرُ وَٱلۡأَنصَابُ وَٱلۡأَزۡلَٰمُ رِجۡسٞ مِّنۡ عَمَلِ ٱلشَّيۡطَٰنِ﴾⟪5:90⟫ إلى قوله تعالى: ﴿فَهَلۡ أَنتُم مُّنتَهُونَ﴾⟪5:91⟫ وعلى قريب من هذا الكلام في الميسر، لكن كان أمره أخف، ومن الناس من جعل كل ما فيه خطر ومقامرة ميسرا، ومنهم من قاسه عليه، وقد روي عن النبي- عليه السلام- \" من لعب بالنرد فقد عصى الله ورسوله \"، وقرئ: إثم كبير وكثير، فكبير لقوله تعالي: ﴿إِن تَجۡتَنِبُواْ كَبَآئِرَ مَا تُنۡهَوۡنَ عَنۡهُ﴾⟪4:31⟫ الآية، وبقوله الله: ﴿إِنَّ ٱلشِّرۡكَ لَظُلۡمٌ عَظِيمٞ﴾⟪31:13⟫ وعظيم وكبير متلازمان، ولأن جلهم قرأ: ﴿أَكۡبَرُ مِن نَّفۡعِهِمَاۗ﴾⟪2:219⟫، ومن قرأ الكثير فنظر منه إلي ما روي عن النبي - صلى الله عليه وسلم - في صفة الخمر ومشتريها وبائعها: \" لعن الله عشرة: مشتريها، وبائعها وعاصرها، والمعتصرة له، وحاملها، والمحمولة إليه، وساقيها وشاربها، وآكل ثمنها .. \".\n⟦1:452⟧\nوقوله:\n﴿وَيَسۡـَٔلُونَكَ مَاذَا يُنفِقُونَۖ﴾⟪2:219⟫ إن قيل؟ كيف أعيد السؤال عما ينفقون وجواب بين الجوابين؟\nقيل: أما الأول: فسؤال عن الجنس الذي ينفق، وعمن ينفق عليه، فبين لهم الأمران، وأما السؤال هاهنا فعن القدر المنفق، فأجيبوا بحسبه، فبين أن الذي ينفق هو العفو، وقال ابن عباس: هو الفضل عن الغني، وهو الذي قال الشاعر:\nأذا أنت أعطيت الغني ثم لم تجد ...\nبفضل الغني ألفيت مالك حامد\nوقال الحسن وعطاء:\nهو القصد الذي لا إسراف فيه ولا إقتار، وقال مجاهد:\nهو الصدقة المفروضة، وكل ذلك مراد، فإن أفل ما تطيب به نفس المسلم هو الصدقة الواجبة، ومن لم تطب نفسه فليس بتام الإيمان، ثم منهم من تطيب نفسه ببذل جل ماله، ومنهم من تطيب لكل ماله، كأبي بكر- رضي الله عنه- فإذن العفو متناول لما هو واجب ولما هو تبرع، وقرئ (العفو) بالرفع والنصب، وذلك لتقديرين مختلفين في ماذا، فإن ماذا تارة تقدر تقدير اسم واحد، فيكون مفعول ينفقون يحق أنه المطابق له بالنصب، وتارة يقدر تقدير اسمين مبتدأ وخبر، فيكون جوابه المطابق له رفعا أي: \" هو العفو \"، وقوله: ﴿كَذَٰلِكَ يُبَيِّنُ ٱللَّهُ لَكُمُ ٱلۡأٓيَٰتِ﴾⟪2:219⟫ فيه حث على تجنب الخمر والميسر، وتنبيه على تحريمهما، فإن في التفكر في الدنيا والآخرة معرفتهما ومعرفة منافعهما، وأن النفع القليل في الدنيا لا يجب أن يشترى بكثير الإثم في الآخرة ..\n⟦1:453⟧"}, {"a": [220], "v": 1, "p": 453, "ev": 1, "ep": 454, "sid": 454, "t": "قوله - عز وجل -:\n﴿فِي ٱلدُّنۡيَا وَٱلۡأٓخِرَةِۗ وَيَسۡـَٔلُونَكَ عَنِ ٱلۡيَتَٰمَىٰۖ قُلۡ إِصۡلَاحٞ لَّهُمۡ خَيۡرٞۖ وَإِن تُخَالِطُوهُمۡ فَإِخۡوَٰنُكُمۡۚ وَٱللَّهُ يَعۡلَمُ ٱلۡمُفۡسِدَ مِنَ ٱلۡمُصۡلِحِۚ وَلَوۡ شَآءَ ٱللَّهُ لَأَعۡنَتَكُمۡۚ إِنَّ ٱللَّهَ عَزِيزٌ حَكِيمٞ﴾⟪2:220⟫\nالآية (220) - سورة البقرة.\nالخلط: الجمع بين أجزاء شينين، سواء \" كانا مانعين، أو غير مانعين فهو أخص من المزج، يقال للصديق: الخلط، وهو دون الخليل، والخلاط وداء يخلط الجوف، وآفة تعتري العقل، والتخليط أن يخلط بالأمر ما يفسده، والإعنات من: عنت العظم عنتا، أصابه وهي أوكسر، وقد أعنته، وكل ما يؤثم أو يشق عنت، ولما أكثر الله تعالى التحذير من مال اليتيم في نحو قوله: ﴿وَلَا تَقۡرَبُواْ مَالَ ٱلۡيَتِيمِ إِلَّا بِٱلَّتِي هِيَ أَحۡسَنُ﴾ وقوله: ﴿إِنَّ ٱلَّذِينَ يَأۡكُلُونَ أَمۡوَٰلَ ٱلۡيَتَٰمَىٰ﴾⟪4:10⟫، وقوله: ﴿وَءَاتُواْ ٱلۡيَتَٰمَىٰٓ أَمۡوَٰلَهُمۡۖ﴾⟪4:2⟫ الآية، تحرجوا عن تناول ماله ومخالطته، فبين تعالي أن حق الإنسان أن يتحرى الصلاح له، وأن لا ضير في مخالطته أي مصاهرته.\nوسائر أنواع المخالطة، وبين أنه أخوهم، وذلك إشارة إلى نحو قوله: ﴿إِنَّمَا ٱلۡمُؤۡمِنُونَ إِخۡوَةٞ﴾⟪49:10⟫، وقوله: ﴿بَعۡضَكُمۡ عَلَىٰ بَعۡضٖۚ﴾، ونبه بقوله: ﴿وَٱللَّهُ يَعۡلَمُ ٱلۡمُفۡسِدَ مِنَ ٱلۡمُصۡلِحِۚ﴾⟪2:220⟫ أن الله تعالى لا تخفى عليه مقاصد الإنسان فيما يفعله معهم، وبين بقوله: ﴿وَلَوۡ شَآءَ ٱللَّهُ لَأَعۡنَتَكُمۡۚ﴾⟪2:220⟫ أنه لم يقصد إعناتا فيما أوصاهم به في هذه الآيات المختلفة ...\n⟦1:454⟧"}];
